set description = excluded.description,
    applied_at = now();

-- ── Per-user notification preferences (095_notification_preferences.sql) ──────
-- Verbatim from 095_notification_preferences.sql: per-event-type push toggles,
-- three categories (activity/payments/periods), default all-on (GVM-119).

create table if not exists public.notification_preferences (
  user_id uuid primary key,
  activity_enabled boolean not null default true,
  payments_enabled boolean not null default true,
  periods_enabled boolean not null default true,
  updated_at timestamptz not null default now()
);

comment on table public.notification_preferences is
  'Per-user push notification toggles (GVM-119). Three categories (activity/payments/periods), default all-on. Read by the govehlo-web push hooks (service role) to skip a recipient who has muted a category.';

alter table public.notification_preferences enable row level security;

drop policy if exists "Users manage own notification preferences" on public.notification_preferences;
create policy "Users manage own notification preferences" on public.notification_preferences
  for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- Read the current user's prefs, defaulting every category to enabled when no row
-- exists yet (the all-on default).
create or replace function public.get_notification_preferences()
returns table (activity_enabled boolean, payments_enabled boolean, periods_enabled boolean)
language sql
stable
security definer
set search_path = public
as $$
  select
    coalesce(np.activity_enabled, true),
    coalesce(np.payments_enabled, true),
    coalesce(np.periods_enabled, true)
  from (select auth.uid() as uid) me
  left join public.notification_preferences np on np.user_id = me.uid;
$$;

revoke all on function public.get_notification_preferences() from public;
grant execute on function public.get_notification_preferences() to authenticated;

-- Upsert the current user's prefs. Null args coalesce to enabled.
create or replace function public.set_notification_preferences(
  activity boolean,
  payments boolean,
  periods boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Notification preferences require a signed-in user' using errcode = '42501';
  end if;
  insert into public.notification_preferences (user_id, activity_enabled, payments_enabled, periods_enabled, updated_at)
  values (v_uid, coalesce(activity, true), coalesce(payments, true), coalesce(periods, true), now())
  on conflict (user_id) do update
  set activity_enabled = excluded.activity_enabled,
      payments_enabled = excluded.payments_enabled,
      periods_enabled = excluded.periods_enabled,
      updated_at = now();
end;
$$;

revoke all on function public.set_notification_preferences(boolean, boolean, boolean) from public;
grant execute on function public.set_notification_preferences(boolean, boolean, boolean) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('095_notification_preferences',
        'Per-user notification preferences table + get/set RPCs (GVM-119) — 3 categories (activity/payments/periods), default all-on; push hooks filter recipients.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();


-- ── Migration 096: purge notification_preferences on account deletion (GV-229) ──
-- Verbatim from 096_purge_notification_preferences_on_delete.sql: re-declare
-- delete_my_account (off migration 072) + a notification_preferences purge.
create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := public.current_user_email();
  v_member record;
  v_old_name text;
  v_first_name text;
  v_anon_name text;
  v_suffix integer;
  v_no_other_active boolean;
  v_successor record;
  v_ledgers_scrubbed integer := 0;
  v_ledgers_deleted integer := 0;
  v_admins_promoted integer := 0;
begin
  if v_uid is null or v_email is null then
    raise exception 'Account deletion requires a signed-in user' using errcode = '42501';
  end if;

  -- Let the settlement lock trigger (GV-199) know these writes are GDPR PII
  -- scrubs, not settlement edits, so its closed-period rejection stands aside.
  -- Transaction-local, so it clears automatically at commit/rollback.
  perform set_config('govehlo.pii_scrub', '1', true);

  for v_member in
    select lm.id, lm.ledger_id, lm.name, lm.role, lm.is_active
    from public.ledger_members lm
    where lm.email is not null
      and lower(lm.email) = v_email
  loop
    v_old_name := v_member.name;
    v_first_name := split_part(v_old_name, ' ', 1);

    -- No other active member left? The workspace dies with this account: nobody
    -- could ever access it again, so full deletion is the cleanest erasure.
    -- Every child table references ledgers(id) with on delete cascade.
    select not exists (
      select 1
      from public.ledger_members lm2
      where lm2.ledger_id = v_member.ledger_id
        and lm2.is_active = true
        and lm2.id <> v_member.id
    ) into v_no_other_active;
    if v_no_other_active then
      delete from public.ledgers l where l.id = v_member.ledger_id;
      v_ledgers_deleted := v_ledgers_deleted + 1;
      continue;
    end if;

    -- Admin succession: never leave a live workspace admin-less. Promote the
    -- longest-standing active member and say so in the feed (system actor).
    if v_member.is_active and v_member.role = 'admin' and not exists (
      select 1
      from public.ledger_members lm3
      where lm3.ledger_id = v_member.ledger_id
        and lm3.is_active = true
        and lm3.role = 'admin'
        and lm3.id <> v_member.id
    ) then
      select lm4.id, lm4.name
      into v_successor
      from public.ledger_members lm4
      where lm4.ledger_id = v_member.ledger_id
        and lm4.is_active = true
        and lm4.id <> v_member.id
      order by lm4.created_at asc, lm4.id asc
      limit 1;

      update public.ledger_members lm5
      set role = 'admin', updated_at = now()
      where lm5.id = v_successor.id;

      insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata)
      values (
        v_member.ledger_id,
        'member_promoted',
        v_successor.name || ' er nu administrator',
        'Automatisk, fordi den tidligere administrator slettede sin konto',
        null,
        null,
        v_successor.id,
        jsonb_build_object('reason', 'account_deleted')
      );
      v_admins_promoted := v_admins_promoted + 1;
    end if;

    -- Per-ledger-unique anonymized name (unique(ledger_id, name) would reject a
    -- second 'Slettet medlem' in the same group).
    v_anon_name := 'Slettet medlem';
    v_suffix := 1;
    while exists (
      select 1
      from public.ledger_members lm6
      where lm6.ledger_id = v_member.ledger_id
        and lm6.name = v_anon_name
        and lm6.id <> v_member.id
    ) loop
      v_suffix := v_suffix + 1;
      v_anon_name := 'Slettet medlem ' || v_suffix;
    end loop;

    -- Authored free text: trip notes are the creator's words, not car facts.
    update public.trips t
    set note = null, updated_at = now()
    where t.ledger_id = v_member.ledger_id
      and t.created_by_member_id = v_member.id
      and t.note is not null;

    -- Bookings: purposes are authored text; future bookings would block the car
    -- for a person who no longer exists.
    update public.car_bookings cb
    set purpose = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.purpose is not null;

    -- Structured fuel stop (migration 063): the from/to labels + lat/lng are the
    -- member's route history — potentially their home address. Null the whole
    -- jsonb; station coords are public, but from/to are personal, so simplest-
    -- correct wins (GV-197).
    update public.car_bookings cb
    set fuel_stop = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.fuel_stop is not null;

    update public.car_bookings cb
    set deleted_at = now(), updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and cb.member_id = v_member.id
      and cb.start_at > now()
      and cb.deleted_at is null;

    -- Chat: blank + soft-delete their messages (the app already filters deleted).
    update public.messages msg
    set body = '', deleted_at = coalesce(msg.deleted_at, now())
    where msg.ledger_id = v_member.ledger_id
      and msg.sender_member_id = v_member.id;

    -- Feed events: drop stored emails and replace the member's name inside titles
    -- and bodies they authored or are targeted by. Events self-expire after 30
    -- days, so this is belt-and-braces on top of bounded retention. Very short
    -- first names (< 3 chars) are skipped for the substring pass — the collision
    -- risk with unrelated words outweighs the residual exposure.
    if char_length(v_first_name) < 3 then
      v_first_name := v_old_name;
    end if;
    update public.ledger_events ev
    set actor_email = case when ev.actor_member_id = v_member.id then null else ev.actor_email end,
        target_email = case when ev.target_member_id = v_member.id then null else ev.target_email end,
        title = replace(replace(ev.title, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem'),
        body = replace(replace(ev.body, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem')
    where ev.ledger_id = v_member.ledger_id
      and (ev.actor_member_id = v_member.id or ev.target_member_id = v_member.id);

    -- Archived snapshots: closed periods keep their maths, but the name fields
    -- inside people[] / settlements[] must stop identifying the person. The
    -- entry fingerprint (migration 054) covers trip/fuel ids only, never names,
    -- so this rewrite cannot invalidate any integrity check.
    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{people}',
      (
        select coalesce(jsonb_agg(
          case when person ->> 'id' = v_member.id::text
            then jsonb_set(person, '{name}', to_jsonb(v_anon_name))
            else person
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(sp.snapshot_json -> 'people') as person
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'people') = 'array';

    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{settlements}',
      (
        select coalesce(jsonb_agg(
          case when settled ->> 'toId' = v_member.id::text
            then jsonb_set(settled, '{toName}', to_jsonb(v_anon_name))
            else settled
          end
        ), '[]'::jsonb)
        from (
          select case when raw ->> 'fromId' = v_member.id::text
            then jsonb_set(raw, '{fromName}', to_jsonb(v_anon_name))
            else raw
          end as settled
          from jsonb_array_elements(sp.snapshot_json -> 'settlements') as raw
        ) as renamed
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'settlements') = 'array';

    -- Invites addressed to this email in this ledger.
    update public.ledger_invites li
    set invited_email = null, updated_at = now()
    where li.ledger_id = v_member.ledger_id
      and lower(coalesce(li.invited_email, '')) = v_email;

    -- Finally the member row itself. Role drops to 'member' (succession above
    -- already ensured another admin exists when one was needed).
    update public.ledger_members lm7
    set name = v_anon_name,
        email = null,
        mobilepay_phone = null,
        role = 'member',
        is_active = false,
        updated_at = now()
    where lm7.id = v_member.id;

    -- Feed transparency, in app voice, without re-publishing the old name.
    insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
    values (
      v_member.ledger_id,
      'member_deleted',
      'Et medlem slettede sin konto',
      v_anon_name || ' er anonymiseret. Gruppens regnskab er uændret.',
      null,
      null,
      jsonb_build_object('member_id', v_member.id)
    );

    v_ledgers_scrubbed := v_ledgers_scrubbed + 1;
  end loop;

  -- Cross-ledger cleanup keyed by identity rather than membership.
  delete from public.push_subscriptions ps
  where lower(ps.user_email) = v_email;

  delete from public.ledger_onboarding_rate_limits rl
  where lower(rl.actor_email) = v_email;

  update public.owner_activity_log oal
  set actor_email = null, actor_user_id = null
  where oal.actor_user_id = v_uid
     or lower(coalesce(oal.actor_email, '')) = v_email;

  -- Push tokens die with the account (migration 057): match by user id and by
  -- the scrubbed email so nothing keeps addressing this person's devices.
  delete from public.expo_push_tokens ept
  where ept.user_id = v_uid
     or lower(ept.email) = v_email;


  -- Purge this user's notification preferences (GV-229). No PII (three booleans
  -- + a uuid), but data minimisation says don't leave an orphaned row behind.
  delete from public.notification_preferences np where np.user_id = v_uid;

  -- Kill the credentials last: cascades sessions/identities, frees the email for
  -- a fresh sign-up. The caller's JWT stays technically valid until expiry but no
  -- longer matches any member (email scrubbed), so RLS yields nothing.
  delete from auth.users au where au.id = v_uid;

  return jsonb_build_object(
    'ledgers_scrubbed', v_ledgers_scrubbed,
    'ledgers_deleted', v_ledgers_deleted,
    'admins_promoted', v_admins_promoted
  );
end;
$$;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('096_purge_notification_preferences_on_delete',
        'delete_my_account also purges notification_preferences on account deletion (GV-229) — data minimisation for the GVM-119 prefs row.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 097: tighten trips read policy to is_ledger_member (GV-176) — the one
-- remaining loose ledger-scoped read policy (email match with no is_active check).
drop policy if exists "Ledger members can read trips" on public.trips;
create policy "Ledger members can read trips" on public.trips
  for select to authenticated
  using (public.is_ledger_member(ledger_id));

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('097_tighten_trips_read_policy',
        'trips read policy uses is_ledger_member (requires is_active) instead of an email-only match, so a deactivated member whose email still matches can no longer read trips (GV-176).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 098: per-workspace operator override for the settlement safety rules
-- (GV-158). Two boolean flags on ledgers (default true = current enforced
-- behaviour); enforce_settlement_entry_lock consults rule_lock_period_after_payment.
alter table public.ledgers
  add column if not exists rule_lock_period_after_payment boolean not null default true;

alter table public.ledgers
  add column if not exists rule_require_requests_before_close boolean not null default true;

-- Re-declared off migration 088 (newest prior body) with ONE addition: a
-- per-workspace override lookup. When the ledger's rule_lock_period_after_payment
-- flag is false, both the closed-period rejection and the requested/paid lock are
-- skipped for that ledger. Only an explicit false disables the rail; a null (no
-- ledger row resolved) keeps the always-on behaviour (GV-158).
create or replace function public.enforce_settlement_entry_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ledger_id text;
  v_period_id uuid;
  v_trip_deleted_at timestamptz;
  v_guard boolean := false;
  v_check_period_id uuid;
  v_period_closed boolean;
  v_rule_lock boolean;
begin
  if tg_table_name = 'trip_participants' then
    -- Participants have no ledger/period of their own; inherit from the trip.
    -- Changing who shares a trip changes the split, so any insert/update/delete
    -- is guarded unless the parent trip is already a tombstone or is gone.
    if tg_op = 'DELETE' then
      select t.ledger_id, t.period_id, t.deleted_at
        into v_ledger_id, v_period_id, v_trip_deleted_at
        from public.trips t
        where t.id = old.trip_id;
    else
      select t.ledger_id, t.period_id, t.deleted_at
        into v_ledger_id, v_period_id, v_trip_deleted_at
        from public.trips t
        where t.id = new.trip_id;
    end if;

    v_guard := v_ledger_id is not null and v_trip_deleted_at is null;

  elsif tg_op = 'INSERT' then
    v_ledger_id := new.ledger_id;
    v_period_id := new.period_id;
    -- Adding a live entry to a settling period changes the totals.
    v_guard := new.deleted_at is null;

  elsif tg_op = 'DELETE' then
    v_ledger_id := old.ledger_id;
    v_period_id := old.period_id;
    -- Removing a live entry changes the totals; purging a tombstone does not.
    v_guard := old.deleted_at is null;

  else -- UPDATE on trips / fuel_payments / workspace_expenses
    v_ledger_id := coalesce(new.ledger_id, old.ledger_id);
    v_period_id := coalesce(old.period_id, new.period_id);

    if tg_table_name = 'trips' then
      v_guard := (new.start_km is distinct from old.start_km)
              or (new.end_km is distinct from old.end_km)
              or (new.trip_date is distinct from old.trip_date)
              or (new.driver_member_id is distinct from old.driver_member_id)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    elsif tg_table_name = 'fuel_payments' then
      v_guard := (new.amount is distinct from old.amount)
              or (new.liters is distinct from old.liters)
              or (new.payer_member_id is distinct from old.payer_member_id)
              or (new.payment_date is distinct from old.payment_date)
              or (new.full_tank is distinct from old.full_tank)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    elsif tg_table_name = 'workspace_expenses' then
      v_guard := (new.amount_dkk is distinct from old.amount_dkk)
              or (new.paid_by_member_id is distinct from old.paid_by_member_id)
              or (new.split_rule is distinct from old.split_rule)
              or (new.split_config is distinct from old.split_config)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    end if;

    -- Editing a row that is a tombstone before and after the change is a no-op
    -- for settlement; leave it alone.
    if old.deleted_at is not null and new.deleted_at is not null then
      v_guard := false;
    end if;
  end if;

  -- Per-workspace override (GV-158): an operator can disable the lock-after-payment
  -- safety rail for a single workspace via the admin console. Default true keeps the
  -- always-on behaviour below; when a ledger's rule_lock_period_after_payment is
  -- false, skip BOTH the closed-period rejection and the requested/paid lock so its
  -- members can edit freely. Only an explicit false disables the rail — a null (no
  -- ledger row resolved) leaves the rail on.
  if v_ledger_id is not null then
    select l.rule_lock_period_after_payment
      into v_rule_lock
      from public.ledgers l
      where l.id = v_ledger_id;
    if v_rule_lock is false then
      if tg_op = 'DELETE' then
        return old;
      end if;
      return new;
    end if;
  end if;

  -- Closed-period rejection (GV-199): no path may add, change, or remove an entry
  -- that belongs to a closed settlement period. Runs before the requested/paid
  -- lock and covers every attached table. delete_my_account's GDPR scrubs set
  -- the transaction-local govehlo.pii_scrub GUC to opt out — those touch only
  -- non-settlement columns (e.g. trip note) and must succeed on closed rows.
  if coalesce(current_setting('govehlo.pii_scrub', true), '') <> '1' then
    -- trip_participants has no period_id column, so it must use the parent trip's
    -- period resolved above; only the row-owning tables carry old/new.period_id
    -- (dereferencing it on trip_participants raised 'record has no field period_id'
    -- and broke all trip logging/editing — GV-225).
    if tg_table_name = 'trip_participants' then
      v_check_period_id := v_period_id;
    else
      v_check_period_id := case when tg_op = 'DELETE' then old.period_id else new.period_id end;
    end if;
    if v_check_period_id is not null then
      select (sp.status = 'closed' or sp.closed_at is not null)
        into v_period_closed
        from public.settlement_periods sp
        where sp.id = v_check_period_id;
      if v_period_closed then
        raise exception
          'This settlement period is closed — entries can no longer be added or changed.'
          using errcode = '22023';
      end if;
    end if;
  end if;

  if v_guard and public.settlement_entry_is_locked(v_ledger_id, v_period_id) then
    raise exception
      'This settlement period is locked because a payment has been requested or paid. Reopen the payment before changing trips or fuel logs.'
      using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('098_settlement_rule_overrides',
        'Per-workspace operator override for the settlement safety rules (GV-158): rule_lock_period_after_payment + rule_require_requests_before_close boolean columns on ledgers (default true = current enforced behaviour). enforce_settlement_entry_lock (re-declared off 088) skips the closed-period rejection and requested/paid lock for a ledger whose rule_lock_period_after_payment is false. rule_require_requests_before_close is stored only — that rule has no database enforcement (close_settlement_period never checked request coverage), so the flag drives the operator toggle and any future client use.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 099: RLS security fixes (GV-243). Drop the forgeable settlement_periods
-- and ledger_events insert policies (no client inserts either table directly; all
-- legitimate writes are SECURITY DEFINER, so RLS default-deny is safe). Re-declare
-- enforce_settlement_entry_lock so the per-workspace override relaxes only the
-- requested/paid lock — the closed-period rejection is always enforced. These blocks
-- win on replay over the original 005 policy creations above.
drop policy if exists "Ledger members can insert periods" on public.settlement_periods;

drop policy if exists "Ledger members can insert ledger events" on public.ledger_events;

create or replace function public.enforce_settlement_entry_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ledger_id text;
  v_period_id uuid;
  v_trip_deleted_at timestamptz;
  v_guard boolean := false;
  v_check_period_id uuid;
  v_period_closed boolean;
  v_rule_lock boolean;
begin
  if tg_table_name = 'trip_participants' then
    -- Participants have no ledger/period of their own; inherit from the trip.
    -- Changing who shares a trip changes the split, so any insert/update/delete
    -- is guarded unless the parent trip is already a tombstone or is gone.
    if tg_op = 'DELETE' then
      select t.ledger_id, t.period_id, t.deleted_at
        into v_ledger_id, v_period_id, v_trip_deleted_at
        from public.trips t
        where t.id = old.trip_id;
    else
      select t.ledger_id, t.period_id, t.deleted_at
        into v_ledger_id, v_period_id, v_trip_deleted_at
        from public.trips t
        where t.id = new.trip_id;
    end if;

    v_guard := v_ledger_id is not null and v_trip_deleted_at is null;

  elsif tg_op = 'INSERT' then
    v_ledger_id := new.ledger_id;
    v_period_id := new.period_id;
    -- Adding a live entry to a settling period changes the totals.
    v_guard := new.deleted_at is null;

  elsif tg_op = 'DELETE' then
    v_ledger_id := old.ledger_id;
    v_period_id := old.period_id;
    -- Removing a live entry changes the totals; purging a tombstone does not.
    v_guard := old.deleted_at is null;

  else -- UPDATE on trips / fuel_payments / workspace_expenses
    v_ledger_id := coalesce(new.ledger_id, old.ledger_id);
    v_period_id := coalesce(old.period_id, new.period_id);

    if tg_table_name = 'trips' then
      v_guard := (new.start_km is distinct from old.start_km)
              or (new.end_km is distinct from old.end_km)
              or (new.trip_date is distinct from old.trip_date)
              or (new.driver_member_id is distinct from old.driver_member_id)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    elsif tg_table_name = 'fuel_payments' then
      v_guard := (new.amount is distinct from old.amount)
              or (new.liters is distinct from old.liters)
              or (new.payer_member_id is distinct from old.payer_member_id)
              or (new.payment_date is distinct from old.payment_date)
              or (new.full_tank is distinct from old.full_tank)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    elsif tg_table_name = 'workspace_expenses' then
      v_guard := (new.amount_dkk is distinct from old.amount_dkk)
              or (new.paid_by_member_id is distinct from old.paid_by_member_id)
              or (new.split_rule is distinct from old.split_rule)
              or (new.split_config is distinct from old.split_config)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    end if;

    -- Editing a row that is a tombstone before and after the change is a no-op
    -- for settlement; leave it alone.
    if old.deleted_at is not null and new.deleted_at is not null then
      v_guard := false;
    end if;
  end if;

  -- Per-workspace override (GV-158, split by GV-243): an operator can disable the
  -- lock-after-payment safety rail for a single workspace via the admin console. The
  -- override is SPLIT across the two protections it used to skip together:
  --   * the requested/paid settlement lock (further below) IS skipped when the flag
  --     is false, so members can freely edit trips/fuel in an OPEN period.
  --   * the closed-period rejection (below) is NOT skipped by this flag — archived
  --     rows in a closed period must always match that period's frozen snapshot_json,
  --     so the closed lock stays enforced regardless of the override.
  -- Only an explicit false relaxes the requested/paid lock; a null (no ledger row
  -- resolved) keeps the always-on behaviour. This lookup no longer returns early.
  if v_ledger_id is not null then
    select l.rule_lock_period_after_payment
      into v_rule_lock
      from public.ledgers l
      where l.id = v_ledger_id;
  end if;

  -- Closed-period rejection (GV-199): no path may add, change, or remove an entry
  -- that belongs to a closed settlement period. Runs before the requested/paid
  -- lock, covers every attached table, and is NOT affected by the override flag
  -- above (GV-243). delete_my_account's GDPR scrubs set the transaction-local
  -- govehlo.pii_scrub GUC to opt out — those touch only non-settlement columns
  -- (e.g. trip note) and must succeed on closed rows.
  if coalesce(current_setting('govehlo.pii_scrub', true), '') <> '1' then
    -- trip_participants has no period_id column, so it must use the parent trip's
    -- period resolved above; only the row-owning tables carry old/new.period_id
    -- (dereferencing it on trip_participants raised 'record has no field period_id'
    -- and broke all trip logging/editing — GV-225).
    if tg_table_name = 'trip_participants' then
      v_check_period_id := v_period_id;
    else
      v_check_period_id := case when tg_op = 'DELETE' then old.period_id else new.period_id end;
    end if;
    if v_check_period_id is not null then
      select (sp.status = 'closed' or sp.closed_at is not null)
        into v_period_closed
        from public.settlement_periods sp
        where sp.id = v_check_period_id;
      if v_period_closed then
        raise exception
          'This settlement period is closed — entries can no longer be added or changed.'
          using errcode = '22023';
      end if;
    end if;
  end if;

  -- Requested/paid settlement lock — this is the only protection the per-workspace
  -- override relaxes: skipped when the ledger's rule_lock_period_after_payment is
  -- false (GV-243). The closed-period rejection above always runs.
  if v_guard and v_rule_lock is not false
     and public.settlement_entry_is_locked(v_ledger_id, v_period_id) then
    raise exception
      'This settlement period is locked because a payment has been requested or paid. Reopen the payment before changing trips or fuel logs.'
      using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('099_rls_security_fixes',
        'RLS security fixes (GV-243): drop the forgeable "Ledger members can insert periods" policy on settlement_periods and "Ledger members can insert ledger events" policy on ledger_events (both had only is_ledger_member checks; no client inserts either table directly, all legitimate writes are SECURITY DEFINER, so RLS default-deny is safe). Re-declare enforce_settlement_entry_lock (off migration 088/098) so the per-workspace rule_lock_period_after_payment override relaxes only the requested/paid lock — the closed-period rejection now always applies so archived rows cannot diverge from the period''s frozen snapshot_json.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 100 mirror: fix check_owner_rate_limit 42702 ambiguity (GV-252) ──
-- Re-declares the limiter with #variable_conflict use_column; the actor_email
-- parameter shadowed the column in the ON CONFLICT target, so the RPC threw on
-- every call since 049. Last definition wins on replay.

create or replace function public.check_owner_rate_limit(
  actor_email text,
  limit_action text default 'owner.api',
  max_attempts integer default 60,
  window_seconds integer default 60
)
returns table (
  allowed boolean,
  attempts integer,
  limit_value integer,
  retry_after_seconds integer
)
language plpgsql
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  safe_email text := nullif(lower(btrim(coalesce(actor_email, ''))), '');
  safe_action text := coalesce(nullif(btrim(coalesce(limit_action, '')), ''), 'owner.api');
  safe_max integer := greatest(coalesce(max_attempts, 60), 1);
  safe_window integer := greatest(coalesce(window_seconds, 60), 1);
  window_start timestamptz;
  current_attempts integer;
begin
  if safe_email is null then
    raise exception 'actor_email is required for owner rate limiting' using errcode = 'P0001';
  end if;

  -- Fixed window aligned to safe_window-second boundaries from the epoch.
  window_start := to_timestamp(floor(extract(epoch from now()) / safe_window) * safe_window);

  insert into public.owner_api_rate_limits (actor_email, action, window_started_at, attempts, last_attempt_at)
  values (safe_email, safe_action, window_start, 1, now())
  on conflict (actor_email, action, window_started_at)
  do update set attempts = public.owner_api_rate_limits.attempts + 1,
               last_attempt_at = now()
  returning public.owner_api_rate_limits.attempts into current_attempts;

  return query
  select
    current_attempts <= safe_max,
    current_attempts,
    safe_max,
    greatest(0, ceil(extract(epoch from (window_start + make_interval(secs => safe_window) - now())))::integer);
end;
$$;

revoke all on function public.check_owner_rate_limit(text, text, integer, integer) from public;
revoke all on function public.check_owner_rate_limit(text, text, integer, integer) from anon;
revoke all on function public.check_owner_rate_limit(text, text, integer, integer) from authenticated;
grant execute on function public.check_owner_rate_limit(text, text, integer, integer) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('100_fix_rate_limit_ambiguity',
        'check_owner_rate_limit re-declared with #variable_conflict use_column: the actor_email parameter shadowed the column in the ON CONFLICT target, so the limiter threw 42702 on every call since 049 - fail-closed proxies blocked first attempts, fail-open callers enforced nothing (GV-252).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 101 mirror: reassignment protection + close invariants (GV-253) ──
-- FIX 1: one shared BEFORE UPDATE trigger lets only a ledger admin or the row
-- creator change the identity-bearing member column on trips/fuel_payments/
-- car_bookings, covering both the SECURITY DEFINER upsert RPCs and direct updates.
-- FIX 2: close_settlement_period (re-declared off 087) enforces
-- rule_require_requests_before_close. FIX 3: the new open period is labelled in
-- Danish ('Juli 2026') instead of English 'Current period'. Last definition wins.

create or replace function public.enforce_identity_reassignment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ledger_id text := new.ledger_id;
  v_actor_member_id uuid;
  v_old_identity uuid;
  v_new_identity uuid;
  v_creator_member_id uuid := old.created_by_member_id;
begin
  -- Identity-bearing member column per table (GV-253). Any other table falls
  -- straight through untouched.
  if tg_table_name = 'trips' then
    v_old_identity := old.driver_member_id;
    v_new_identity := new.driver_member_id;
  elsif tg_table_name = 'fuel_payments' then
    v_old_identity := old.payer_member_id;
    v_new_identity := new.payer_member_id;
  elsif tg_table_name = 'car_bookings' then
    v_old_identity := old.member_id;
    v_new_identity := new.member_id;
  else
    return new;
  end if;

  -- Guard only an actual reassignment; an unchanged identity passes through so the
  -- driver / payer / booked member keeps editing every non-identity field.
  if v_new_identity is not distinct from v_old_identity then
    return new;
  end if;

  -- Reassignment is admin-or-creator only. The JWT helpers resolve the real actor
  -- even inside the SECURITY DEFINER upsert RPCs (auth.jwt() is request-scoped),
  -- mirroring how is_ledger_admin / current_ledger_member_id already work there.
  v_actor_member_id := public.current_ledger_member_id(v_ledger_id);
  if not (
    public.is_ledger_admin(v_ledger_id)
    or (v_creator_member_id is not null and v_creator_member_id = v_actor_member_id)
  ) then
    raise exception
      'Only the creator or a ledger admin can reassign who this entry belongs to.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

revoke execute on function public.enforce_identity_reassignment() from public;

