alter table public.ledger_members
  add column if not exists last_seen_at timestamptz;

comment on column public.ledger_members.last_seen_at is
  'Minimal activity metadata (GVM-66): the last time this member''s client sent a presence heartbeat (touch_member_presence). Null means never/unknown. Workspace-visible only, EU-hosted, nulled on account deletion by delete_my_account.';

-- touch_member_presence: the caller stamps their OWN membership's last_seen_at.
-- Resolves the actor via current_ledger_member_id (the same JWT-email -> active
-- member mapping every event-writing RPC uses), so a member can only ever bump
-- their own row. EVENT-FREE by design (no ledger_events insert). Columns are
-- qualified against the target_ledger_id param (ambiguity guard).
create or replace function public.touch_member_presence(target_ledger_id text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_member_id uuid := public.current_ledger_member_id(target_ledger_id);
begin
  if v_member_id is null then
    raise exception 'Caller is not an active member of this ledger' using errcode = '22023';
  end if;

  update public.ledger_members lm
  set last_seen_at = now()
  where lm.id = v_member_id;
end;
$$;

revoke all on function public.touch_member_presence(text) from public;
grant execute on function public.touch_member_presence(text) to authenticated;

-- Deletion cleanup: re-declare delete_my_account off migration 096 (the newest
-- prior definition) with one addition — the member-scrub step also nulls
-- last_seen_at, so a deleted account leaves no residual activity metadata behind.
create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := public.current_user_email();
  v_member record;
  v_old_name text;
  v_first_name text;
  v_anon_name text;
  v_suffix integer;
  v_no_other_active boolean;
  v_successor record;
  v_ledgers_scrubbed integer := 0;
  v_ledgers_deleted integer := 0;
  v_admins_promoted integer := 0;
begin
  if v_uid is null or v_email is null then
    raise exception 'Account deletion requires a signed-in user' using errcode = '42501';
  end if;

  -- Let the settlement lock trigger (GV-199) know these writes are GDPR PII
  -- scrubs, not settlement edits, so its closed-period rejection stands aside.
  -- Transaction-local, so it clears automatically at commit/rollback.
  perform set_config('govehlo.pii_scrub', '1', true);

  for v_member in
    select lm.id, lm.ledger_id, lm.name, lm.role, lm.is_active
    from public.ledger_members lm
    where lm.email is not null
      and lower(lm.email) = v_email
  loop
    v_old_name := v_member.name;
    v_first_name := split_part(v_old_name, ' ', 1);

    -- No other active member left? The workspace dies with this account: nobody
    -- could ever access it again, so full deletion is the cleanest erasure.
    -- Every child table references ledgers(id) with on delete cascade.
    select not exists (
      select 1
      from public.ledger_members lm2
      where lm2.ledger_id = v_member.ledger_id
        and lm2.is_active = true
        and lm2.id <> v_member.id
    ) into v_no_other_active;
    if v_no_other_active then
      delete from public.ledgers l where l.id = v_member.ledger_id;
      v_ledgers_deleted := v_ledgers_deleted + 1;
      continue;
    end if;

    -- Admin succession: never leave a live workspace admin-less. Promote the
    -- longest-standing active member and say so in the feed (system actor).
    if v_member.is_active and v_member.role = 'admin' and not exists (
      select 1
      from public.ledger_members lm3
      where lm3.ledger_id = v_member.ledger_id
        and lm3.is_active = true
        and lm3.role = 'admin'
        and lm3.id <> v_member.id
    ) then
      select lm4.id, lm4.name
      into v_successor
      from public.ledger_members lm4
      where lm4.ledger_id = v_member.ledger_id
        and lm4.is_active = true
        and lm4.id <> v_member.id
      order by lm4.created_at asc, lm4.id asc
      limit 1;

      update public.ledger_members lm5
      set role = 'admin', updated_at = now()
      where lm5.id = v_successor.id;

      insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata)
      values (
        v_member.ledger_id,
        'member_promoted',
        v_successor.name || ' er nu administrator',
        'Automatisk, fordi den tidligere administrator slettede sin konto',
        null,
        null,
        v_successor.id,
        jsonb_build_object('reason', 'account_deleted')
      );
      v_admins_promoted := v_admins_promoted + 1;
    end if;

    -- Per-ledger-unique anonymized name (unique(ledger_id, name) would reject a
    -- second 'Slettet medlem' in the same group).
    v_anon_name := 'Slettet medlem';
    v_suffix := 1;
    while exists (
      select 1
      from public.ledger_members lm6
      where lm6.ledger_id = v_member.ledger_id
        and lm6.name = v_anon_name
        and lm6.id <> v_member.id
    ) loop
      v_suffix := v_suffix + 1;
      v_anon_name := 'Slettet medlem ' || v_suffix;
    end loop;

    -- Authored free text: trip notes are the creator's words, not car facts.
    update public.trips t
    set note = null, updated_at = now()
    where t.ledger_id = v_member.ledger_id
      and t.created_by_member_id = v_member.id
      and t.note is not null;

    -- Bookings: purposes are authored text; future bookings would block the car
    -- for a person who no longer exists.
    update public.car_bookings cb
    set purpose = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.purpose is not null;

    -- Structured fuel stop (migration 063): the from/to labels + lat/lng are the
    -- member's route history — potentially their home address. Null the whole
    -- jsonb; station coords are public, but from/to are personal, so simplest-
    -- correct wins (GV-197).
    update public.car_bookings cb
    set fuel_stop = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.fuel_stop is not null;

    update public.car_bookings cb
    set deleted_at = now(), updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and cb.member_id = v_member.id
      and cb.start_at > now()
      and cb.deleted_at is null;

    -- Chat: blank + soft-delete their messages (the app already filters deleted).
    update public.messages msg
    set body = '', deleted_at = coalesce(msg.deleted_at, now())
    where msg.ledger_id = v_member.ledger_id
      and msg.sender_member_id = v_member.id;

    -- Feed events: drop stored emails and replace the member's name inside titles
    -- and bodies they authored or are targeted by. Events self-expire after 30
    -- days, so this is belt-and-braces on top of bounded retention. Very short
    -- first names (< 3 chars) are skipped for the substring pass — the collision
    -- risk with unrelated words outweighs the residual exposure.
    if char_length(v_first_name) < 3 then
      v_first_name := v_old_name;
    end if;
    update public.ledger_events ev
    set actor_email = case when ev.actor_member_id = v_member.id then null else ev.actor_email end,
        target_email = case when ev.target_member_id = v_member.id then null else ev.target_email end,
        title = replace(replace(ev.title, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem'),
        body = replace(replace(ev.body, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem')
    where ev.ledger_id = v_member.ledger_id
      and (ev.actor_member_id = v_member.id or ev.target_member_id = v_member.id);

    -- Archived snapshots: closed periods keep their maths, but the name fields
    -- inside people[] / settlements[] must stop identifying the person. The
    -- entry fingerprint (migration 054) covers trip/fuel ids only, never names,
    -- so this rewrite cannot invalidate any integrity check.
    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{people}',
      (
        select coalesce(jsonb_agg(
          case when person ->> 'id' = v_member.id::text
            then jsonb_set(person, '{name}', to_jsonb(v_anon_name))
            else person
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(sp.snapshot_json -> 'people') as person
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'people') = 'array';

    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{settlements}',
      (
        select coalesce(jsonb_agg(
          case when settled ->> 'toId' = v_member.id::text
            then jsonb_set(settled, '{toName}', to_jsonb(v_anon_name))
            else settled
          end
        ), '[]'::jsonb)
        from (
          select case when raw ->> 'fromId' = v_member.id::text
            then jsonb_set(raw, '{fromName}', to_jsonb(v_anon_name))
            else raw
          end as settled
          from jsonb_array_elements(sp.snapshot_json -> 'settlements') as raw
        ) as renamed
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'settlements') = 'array';

    -- Invites addressed to this email in this ledger.
    update public.ledger_invites li
    set invited_email = null, updated_at = now()
    where li.ledger_id = v_member.ledger_id
      and lower(coalesce(li.invited_email, '')) = v_email;

    -- Finally the member row itself. Role drops to 'member' (succession above
    -- already ensured another admin exists when one was needed). last_seen_at is
    -- nulled too (GVM-66): activity metadata must not outlive the account.
    update public.ledger_members lm7
    set name = v_anon_name,
        email = null,
        mobilepay_phone = null,
        role = 'member',
        is_active = false,
        last_seen_at = null,
        updated_at = now()
    where lm7.id = v_member.id;

    -- Feed transparency, in app voice, without re-publishing the old name.
    insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
    values (
      v_member.ledger_id,
      'member_deleted',
      'Et medlem slettede sin konto',
      v_anon_name || ' er anonymiseret. Gruppens regnskab er uændret.',
      null,
      null,
      jsonb_build_object('member_id', v_member.id)
    );

    v_ledgers_scrubbed := v_ledgers_scrubbed + 1;
  end loop;

  -- Cross-ledger cleanup keyed by identity rather than membership.
  delete from public.push_subscriptions ps
  where lower(ps.user_email) = v_email;

  delete from public.ledger_onboarding_rate_limits rl
  where lower(rl.actor_email) = v_email;

  update public.owner_activity_log oal
  set actor_email = null, actor_user_id = null
  where oal.actor_user_id = v_uid
     or lower(coalesce(oal.actor_email, '')) = v_email;

  -- Push tokens die with the account (migration 057): match by user id and by
  -- the scrubbed email so nothing keeps addressing this person's devices.
  delete from public.expo_push_tokens ept
  where ept.user_id = v_uid
     or lower(ept.email) = v_email;


  -- Purge this user's notification preferences (GV-229). No PII (three booleans
  -- + a uuid), but data minimisation says don't leave an orphaned row behind.
  delete from public.notification_preferences np where np.user_id = v_uid;

  -- Kill the credentials last: cascades sessions/identities, frees the email for
  -- a fresh sign-up. The caller's JWT stays technically valid until expiry but no
  -- longer matches any member (email scrubbed), so RLS yields nothing.
  delete from auth.users au where au.id = v_uid;

  return jsonb_build_object(
    'ledgers_scrubbed', v_ledgers_scrubbed,
    'ledgers_deleted', v_ledgers_deleted,
    'admins_promoted', v_admins_promoted
  );
end;
$$;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('111_member_last_seen',
        'Persisted member last-seen (GVM-66): ledger_members gains last_seen_at (null = never/unknown); event-free touch_member_presence(target_ledger_id) lets a caller stamp their own membership heartbeat (validates active member, 22023) without writing ledger_events; delete_my_account re-declared off 096 to also null last_seen_at in the member scrub.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ═══════════════════════════════════════════════════════════════════════════
-- Verbatim from 112_release_blockers_remediation.sql (GV-273/274/275). Function
-- bodies below are byte-identical to the migration (schema-equivalence guard).
-- ═══════════════════════════════════════════════════════════════════════════

-- ── GV-273: repairs immutable after their period closes ─────────────────────────
-- Runs BEFORE UPDATE OR DELETE on vehicle_repairs. A repair belongs to the period
-- whose [opened_at, closed_at) window contains its created_at (the moment it was
-- LOGGED — repair_date is display-only and may lie years in the past, exactly as
-- calculate_period_settlement scopes repairs, GV-269). If that period is closed,
-- the row is frozen: both a soft delete (UPDATE of deleted_at) and a hard DELETE
-- are rejected. created_at and ledger_id are immutable, so OLD carries them for
-- both operations. Matches the settlement lock trigger's closed-period rejection
-- style (GV-199): errcode 22023, a single clear sentence.
create or replace function public.enforce_repair_period_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if exists (
    select 1
    from public.settlement_periods sp
    where sp.ledger_id = old.ledger_id
      and sp.closed_at is not null
      and old.created_at >= sp.opened_at
      and old.created_at < sp.closed_at
  ) then
    raise exception
      'This repair belongs to a closed settlement period and can no longer be edited or deleted.'
      using errcode = '22023';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

drop trigger if exists enforce_repair_period_lock on public.vehicle_repairs;
create trigger enforce_repair_period_lock
before update or delete on public.vehicle_repairs
for each row execute function public.enforce_repair_period_lock();

-- ── GV-274.1: upsert_recurring_expense — positive amount + in-window due date ────
-- Re-declared off migration 077 (its newest prior definition; 083 only re-granted
-- it). Everything from 077 is preserved — admin gate, actor resolution, the
-- payer-membership gate, the active-payer gate on INSERT, the cadence/split
-- validation, and the event insert. The only additions (GV-274): a recurring
-- template is a financial record, so its amount must be present and > 0 (rounded
-- to 2 decimals; the coalesce-to-0 is gone) and its next_due_date must be present
-- and within [current_date - 90 days, current_date + 5 years]. On an EDIT a null
-- amount / next_due_date still means "leave unchanged" (the update COALESCEs), but
-- a value that IS supplied is validated. Signature is unchanged, so this is a
-- plain create-or-replace; grants are restated defensively.
create or replace function public.upsert_recurring_expense(
  target_ledger_id text,
  recurring_id_value uuid default null,
  category_value text default 'other',
  description_value text default null,
  amount_value numeric default 0,
  cadence_value text default 'monthly',
  next_due_date_value date default null,
  split_rule_value text default null,
  split_config_value jsonb default null,
  paid_by_value uuid default null,
  is_active_value boolean default true,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  result_id uuid;
  is_new boolean := recurring_id_value is null;
  normalized_event_type text;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can manage recurring expenses' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  if paid_by_value is not null
     and not public.member_belongs_to_ledger(paid_by_value, target_ledger_id) then
    raise exception 'Payer must be a member of this ledger' using errcode = '22023';
  end if;

  if coalesce(cadence_value, 'monthly') not in ('monthly', 'quarterly', 'semiannual', 'yearly') then
    raise exception 'Invalid cadence' using errcode = '22023';
  end if;

  if split_rule_value is not null and split_rule_value not in ('equal', 'usage', 'custom') then
    raise exception 'Invalid split rule' using errcode = '22023';
  end if;

  -- Amount: a recurring template drives every future generated expense, so a
  -- missing or non-positive amount is rejected rather than coalesced to 0
  -- (GV-274). Rounded to 2 decimals. A null on an EDIT leaves it unchanged.
  if amount_value is not null then
    amount_value := round(amount_value, 2);
    if amount_value <= 0 then
      raise exception 'Recurring amount must be greater than zero' using errcode = '22023';
    end if;
  elsif is_new then
    raise exception 'Recurring amount is required' using errcode = '22023';
  end if;

  -- Next due date: required on a new template and, when supplied, within
  -- [current_date - 90 days, current_date + 5 years] — a date decades in the past
  -- would make the generator materialise (then cap) a huge backlog, one far in
  -- the future would never fire (GV-274). A null on an EDIT leaves it unchanged.
  if next_due_date_value is not null then
    if next_due_date_value < (current_date - interval '90 days')::date
       or next_due_date_value > (current_date + interval '5 years')::date then
      raise exception 'Next due date must be within 90 days ago and 5 years ahead' using errcode = '22023';
    end if;
  elsif is_new then
    raise exception 'Next due date is required' using errcode = '22023';
  end if;

  if is_new then
    -- A brand-new template must be paid by an ACTIVE member (GV-208) — its payer
    -- drives every future generated expense. Edits keep the looser membership gate.
    if paid_by_value is not null
       and not public.member_is_active_in_ledger(paid_by_value, target_ledger_id) then
      raise exception 'Payer must be an active member of this ledger' using errcode = '22023';
    end if;

    insert into public.recurring_expenses (
      ledger_id, category, description, amount_dkk, cadence, next_due_date,
      split_rule, split_config, paid_by_member_id, is_active, created_by_member_id
    ) values (
      target_ledger_id,
      coalesce(nullif(category_value, ''), 'other'),
      nullif(description_value, ''),
      amount_value,
      coalesce(nullif(cadence_value, ''), 'monthly'),
      next_due_date_value,
      split_rule_value,
      split_config_value,
      coalesce(paid_by_value, actor_member_id),
      coalesce(is_active_value, true),
      actor_member_id
    )
    returning id into result_id;
    normalized_event_type := 'recurring_expense_added';
  else
    if not exists (
      select 1 from public.recurring_expenses r
      where r.id = recurring_id_value
        and r.ledger_id = target_ledger_id
        and r.deleted_at is null
    ) then
      raise exception 'Recurring expense was not found' using errcode = '22023';
    end if;

    update public.recurring_expenses set
      category          = coalesce(nullif(category_value, ''), category),
      description       = nullif(description_value, ''),
      amount_dkk        = coalesce(amount_value, amount_dkk),
      cadence           = coalesce(nullif(cadence_value, ''), cadence),
      next_due_date     = coalesce(next_due_date_value, next_due_date),
      split_rule        = split_rule_value,
      split_config      = split_config_value,
      paid_by_member_id = coalesce(paid_by_value, paid_by_member_id),
      is_active         = coalesce(is_active_value, is_active),
      updated_at        = now()
    where id = recurring_id_value
      and ledger_id = target_ledger_id;
    result_id := recurring_id_value;
    normalized_event_type := 'recurring_expense_updated';
  end if;

  if nullif(event_title, '') is not null then
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id,
      normalized_event_type,
      event_title,
      coalesce(event_body, ''),
      actor_member_id,
      nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
      jsonb_build_object('category', coalesce(nullif(category_value, ''), 'other'))
    );
  end if;

  return jsonb_build_object(
    'id', result_id,
    'event_type', normalized_event_type
  );
end;
$$;

revoke all on function public.upsert_recurring_expense(text, uuid, text, text, numeric, text, date, text, jsonb, uuid, boolean, text, text) from public;
revoke all on function public.upsert_recurring_expense(text, uuid, text, text, numeric, text, date, text, jsonb, uuid, boolean, text, text) from anon;
grant execute on function public.upsert_recurring_expense(text, uuid, text, text, numeric, text, date, text, jsonb, uuid, boolean, text, text) to authenticated;

-- ── GV-274.2: generate_due_recurring_expenses — 24-occurrence catch-up cap ───────
-- Re-declared off migration 075 (its newest prior definition; 083 only re-granted
-- it). Body is 075 verbatim plus one guard: a single template materialises at most
-- MAX_CATCHUP_OCCURRENCES occurrences per run (24). next_due_date advances only
-- through the occurrences actually processed, so a very stale template is caught up
-- across several runs (bounded per tick, nothing lost) rather than generating an
-- unbounded backlog in one call. Same constant as the scheduler sweep below.
create or replace function public.generate_due_recurring_expenses(
  target_ledger_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  total_generated integer := 0;
  -- Bound the per-template catch-up so one stale template can't materialise an
  -- unbounded backlog in a single run; the remainder catches up on later runs
  -- (GV-274). Same value in generate_all_due_recurring_expenses (the scheduler).
  max_catchup_occurrences constant integer := 24;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can generate recurring expenses' using errcode = '42501';
  end if;

  -- Materialise into the ledger's open period. If none is open (should not happen
  -- after bootstrap, but a period close briefly precedes the next open), do
  -- nothing this run; the next call catches up. FOR SHARE serializes against a
  -- concurrent close (which exclusively locks the period row).
  select sp.id into open_period_id
  from public.settlement_periods sp
  where sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  order by sp.opened_at desc
  limit 1
  for share of sp;

  if open_period_id is null then
    return jsonb_build_object('generated', 0, 'reason', 'no_open_period');
  end if;

  for tmpl in
    select *
    from public.recurring_expenses r
    where r.ledger_id = target_ledger_id
      and r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
    order by r.next_due_date
    for update skip locked
  loop
    due_date := tmpl.next_due_date;
    template_count := 0;
    occurrences := 0;

    while due_date <= current_date and occurrences < max_catchup_occurrences loop
      insert into public.workspace_expenses (
        ledger_id, period_id, category, description, amount_dkk, expense_date,
        split_rule, split_config, paid_by_member_id, created_by_member_id,
        recurring_expense_id, occurrence_date
      ) values (
        target_ledger_id,
        open_period_id,
        tmpl.category,
        tmpl.description,
        tmpl.amount_dkk,
        due_date,
        tmpl.split_rule,
        tmpl.split_config,
        tmpl.paid_by_member_id,
        tmpl.created_by_member_id,
        tmpl.id,
        due_date
      )
      on conflict (recurring_expense_id, occurrence_date)
        where recurring_expense_id is not null do nothing
      returning id into inserted_id;

      if inserted_id is not null then
        template_count := template_count + 1;
      end if;
      inserted_id := null;
      occurrences := occurrences + 1;

      due_date := (case tmpl.cadence
        when 'monthly' then due_date + interval '1 month'
        when 'quarterly' then due_date + interval '3 months'
        when 'semiannual' then due_date + interval '6 months'
        when 'yearly' then due_date + interval '1 year'
        else due_date + interval '1 month'
      end)::date;
    end loop;

    update public.recurring_expenses
      set next_due_date = due_date, last_generated_at = now(), updated_at = now()
    where id = tmpl.id;

    if template_count > 0 then
      insert into public.ledger_events (
        ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
      ) values (
        target_ledger_id,
        'expense_recurring_added',
        'Fast udgift tilføjet',
        coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
          || ' blev automatisk tilføjet og delt.',
        null,
        null,
        jsonb_build_object(
          'category', tmpl.category,
          'recurring_expense_id', tmpl.id,
          'count', template_count
        )
      );
      total_generated := total_generated + template_count;
    end if;
  end loop;

  return jsonb_build_object('generated', total_generated);
end;
$$;

revoke all on function public.generate_due_recurring_expenses(text) from public;
revoke all on function public.generate_due_recurring_expenses(text) from anon;
grant execute on function public.generate_due_recurring_expenses(text) to authenticated;

-- ── GV-274.2 + .3: generate_all_due_recurring_expenses — cap + batch fairness ────
-- Re-declared off migration 110 (its only prior definition). Two changes:
--   * The same MAX_CATCHUP_OCCURRENCES (24) per-template cap as the client RPC.
--   * The candidate-ledger scan now requires an OPEN period to EXIST and orders by
--     the ledger's oldest due next_due_date ascending (GV-274). A ledger with no
--     open period never occupies a batch slot (the inner FOR SHARE would skip it
--     anyway, wasting a slot), and the oldest debt is served first under the
--     batch_limit. The inner open-period FOR SHARE + null-skip stay as a
--     belt-and-braces guard against a period that closes between scan and process.
-- Service-role only (grants restated).
create or replace function public.generate_all_due_recurring_expenses(
  batch_limit integer default 200
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  due_ledger record;
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  ledger_generated integer;
  total_generated integer := 0;
  ledgers_touched integer := 0;
  ledgers_scanned integer := 0;
  -- Same per-template catch-up bound as generate_due_recurring_expenses (GV-274).
  max_catchup_occurrences constant integer := 24;
begin
  for due_ledger in
    -- Only ledgers with a due active template AND an open period to receive it,
    -- oldest debt first, so no-open-period ledgers never occupy a batch slot and
    -- the most overdue ledger is caught up first under batch_limit (GV-274).
    select r.ledger_id
    from public.recurring_expenses r
    where r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and exists (
        select 1
        from public.settlement_periods sp
        where sp.ledger_id = r.ledger_id
          and sp.status = 'open'
          and sp.closed_at is null
      )
    group by r.ledger_id
    order by min(r.next_due_date) asc, r.ledger_id
    limit greatest(coalesce(batch_limit, 200), 0)
  loop
    ledgers_scanned := ledgers_scanned + 1;

    -- Materialise into the ledger's open period. If none is open (a period close
    -- briefly precedes the next open), skip this ledger this run; the next tick catches
    -- up. FOR SHARE serializes against a concurrent close (which exclusively locks the
    -- period row).
    select sp.id into open_period_id
    from public.settlement_periods sp
    where sp.ledger_id = due_ledger.ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    order by sp.opened_at desc
    limit 1
    for share of sp;

    if open_period_id is null then
      open_period_id := null;
      continue;
    end if;

    ledger_generated := 0;

    for tmpl in
      select *
      from public.recurring_expenses r
      where r.ledger_id = due_ledger.ledger_id
        and r.is_active
        and r.deleted_at is null
        and r.next_due_date <= current_date
      order by r.next_due_date
      for update skip locked
    loop
      due_date := tmpl.next_due_date;
      template_count := 0;
      occurrences := 0;

      while due_date <= current_date and occurrences < max_catchup_occurrences loop
        insert into public.workspace_expenses (
          ledger_id, period_id, category, description, amount_dkk, expense_date,
          split_rule, split_config, paid_by_member_id, created_by_member_id,
          recurring_expense_id, occurrence_date
        ) values (
          due_ledger.ledger_id,
          open_period_id,
          tmpl.category,
          tmpl.description,
          tmpl.amount_dkk,
          due_date,
          tmpl.split_rule,
          tmpl.split_config,
          tmpl.paid_by_member_id,
          tmpl.created_by_member_id,
          tmpl.id,
          due_date
        )
        on conflict (recurring_expense_id, occurrence_date)
          where recurring_expense_id is not null do nothing
        returning id into inserted_id;

        if inserted_id is not null then
          template_count := template_count + 1;
        end if;
        inserted_id := null;
        occurrences := occurrences + 1;

        due_date := (case tmpl.cadence
          when 'monthly' then due_date + interval '1 month'
          when 'quarterly' then due_date + interval '3 months'
          when 'semiannual' then due_date + interval '6 months'
          when 'yearly' then due_date + interval '1 year'
          else due_date + interval '1 month'
        end)::date;
      end loop;

      update public.recurring_expenses
        set next_due_date = due_date, last_generated_at = now(), updated_at = now()
      where id = tmpl.id;

      if template_count > 0 then
        insert into public.ledger_events (
          ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
        ) values (
          due_ledger.ledger_id,
          'expense_recurring_added',
          'Fast udgift tilføjet',
          coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
            || ' blev automatisk tilføjet og delt.',
          null,
          null,
          jsonb_build_object(
            'category', tmpl.category,
            'recurring_expense_id', tmpl.id,
            'count', template_count
          )
        );
        ledger_generated := ledger_generated + template_count;
      end if;
    end loop;

    if ledger_generated > 0 then
      ledgers_touched := ledgers_touched + 1;
      total_generated := total_generated + ledger_generated;
    end if;

    open_period_id := null;
  end loop;

  return jsonb_build_object(
    'generated', total_generated,
    'ledgers_touched', ledgers_touched,
    'ledgers_scanned', ledgers_scanned
  );
end;
$$;

revoke execute on function public.generate_all_due_recurring_expenses(integer) from public;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from anon;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from authenticated;
grant execute on function public.generate_all_due_recurring_expenses(integer) to service_role;

-- ── GV-274.4: calculate_period_settlement — credit-only inactive payers ──────────
-- Re-declared off migration 108 (its newest prior definition). The trips/fuel and
-- largest-remainder maths are byte-identical to 108; the ONLY change is that a
-- payer who is an INACTIVE member of the ledger is no longer dropped. Owner
-- decision (2026-07-11): an inactive payer becomes a CREDIT-ONLY participant —
-- credited exactly what they paid (fuel + expense + repair), with ZERO weight in
-- every share split. Concretely:
--   * all_members is the full membership; active_members is the split universe.
--   * period_expenses / period_repairs join all_members (not active_members), so
--     an inactive-payer entry is retained and its cost is still split — but the
--     weight CTEs cross join active_members only, so the split lands entirely on
--     ACTIVE members and the inactive payer bears nothing (largest-remainder
--     semantics unchanged).
--   * settlement_members = active_members UNION any member (active or not) who
--     paid fuel/expense/repair this period; per_member is built from it. An
--     inactive member who paid NOTHING is not a settlement_member and never
--     appears. Fuel already had no active-only join — it was dropped only because
--     per_member was built from active_members — so widening per_member credits
--     inactive fuel payers by the same rule (consistent everywhere).
--   * An inactive payer has no km (km_shares is active-only), no expense_share,
--     no repair_share, so their net is exactly +paid and the period still nets to
--     zero. Signature unchanged; grants restated.
create or replace function public.calculate_period_settlement(
  target_ledger_id text,
  target_period_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_operator_context()
     and not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can calculate settlements' using errcode = '42501';
  end if;

  with active_members as (
    select lm.id, lm.name
    from public.ledger_members lm
    where lm.ledger_id = target_ledger_id
      and lm.is_active = true
  ),
  all_members as (
    -- Every member of the ledger, active or not. Used to retain (not drop) an
    -- entry whose payer has since gone inactive so that payer can be credited
    -- (GV-274, credit-only). is_active decides who lands in settlement_members.
    select lm.id, lm.name, lm.is_active
    from public.ledger_members lm
    where lm.ledger_id = target_ledger_id
  ),
  live_trips as (
    select t.id,
           t.driver_member_id,
           greatest(t.end_km - t.start_km, 0)::numeric as km
    from public.trips t
    where t.ledger_id = target_ledger_id
      and t.period_id = target_period_id
      and t.deleted_at is null
  ),
  trip_assignees as (
    select lt.id as trip_id,
           lt.km,
           coalesce(
             valid_participants.member_ids,
             case when driver_check.id is not null then array[lt.driver_member_id] end
           ) as assignees
    from live_trips lt
    left join lateral (
      select array_agg(distinct tp.member_id) as member_ids
      from public.trip_participants tp
      join active_members am on am.id = tp.member_id
      where tp.trip_id = lt.id
    ) valid_participants on true
    left join active_members driver_check on driver_check.id = lt.driver_member_id
  ),
  km_shares as (
    select shared.member_id,
           ta.km / array_length(ta.assignees, 1) as share_km
    from trip_assignees ta
    cross join lateral unnest(ta.assignees) as shared(member_id)
    where ta.assignees is not null
      and array_length(ta.assignees, 1) > 0
  ),
  member_km as (
    -- Unrounded per-member km, reused both for the settlement km and as the
    -- usage-split weight (the client weights usage on raw km).
    select ks.member_id, sum(ks.share_km) as km_sum
    from km_shares ks
    group by ks.member_id
  ),
  fuel_paid as (
    select fp.payer_member_id as member_id,
           sum(fp.amount)::numeric as paid
    from public.fuel_payments fp
    where fp.ledger_id = target_ledger_id
      and fp.period_id = target_period_id
      and fp.deleted_at is null
      and fp.payer_member_id is not null
    group by fp.payer_member_id
  ),
  ledger_defaults as (
    select l.expense_split_defaults as defaults
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  repairs_mode as (
    -- The workspace rule that governs repair folding (GVM-307). null (old row,
    -- pre-107) behaves like deles_ikke: the mode filter below excludes every
    -- repair, matching a client that has no mode field to read.
    select l.repairs_split_mode as mode
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  period_bounds as (
    -- Repairs have no period_id: a repair counts in the period whose
    -- [opened_at, closed_at) window contains its created_at — the moment it was
    -- LOGGED (GV-269; repair_date is display-only and may lie far in the past).
    -- The settling period is still open here (closed_at null), so its window has
    -- no upper bound.
    select sp.opened_at, sp.closed_at
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
  ),
  period_expenses as (
    -- Live expenses in this period whose payer is a MEMBER of the ledger (active
    -- OR inactive). An inactive payer is retained (credit-only, GV-274) rather
    -- than dropped: its cost is still split (over active members, via the weight
    -- CTEs below), and the payer is credited what they paid. An expense with no
    -- payer or a non-member payer is still skipped entirely.
    select we.id,
           we.amount_dkk,
           we.paid_by_member_id,
           we.split_config,
           coalesce(nullif(we.split_rule, ''),
                    (ld.defaults ->> we.category),
                    'equal') as rule
    from public.workspace_expenses we
    cross join ledger_defaults ld
    join all_members payer on payer.id = we.paid_by_member_id
    where we.ledger_id = target_ledger_id
      and we.period_id = target_period_id
      and we.deleted_at is null
      and we.amount_dkk > 0
  ),
  expense_weights as (
    select pe.id as expense_id,
           pe.amount_dkk,
           am.id as member_id,
           case pe.rule
             when 'usage'  then coalesce(mk.km_sum, 0)
             when 'custom' then coalesce((pe.split_config ->> am.id::text)::numeric, 0)
             else 1::numeric
           end as weight
    from period_expenses pe
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  expense_weight_totals as (
    select expense_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from expense_weights
    group by expense_id
  ),
  expense_cents as (
    -- Largest-remainder split, step 1 (GV-269): per expense, work in integer
    -- oere and compute each member's exact (unrounded) share of them. A
    -- non-positive total weight falls back to equal weights, matching the
    -- pre-108 fallback and the client.
    select ew.expense_id,
           ew.member_id,
           round(ew.amount_dkk * 100) as total_cents,
           round(ew.amount_dkk * 100)
             * (case when ewt.total_weight > 0 then ew.weight else 1 end)
             / (case when ewt.total_weight > 0 then ewt.total_weight else ewt.member_count end)
             as exact_cents
    from expense_weights ew
    join expense_weight_totals ewt using (expense_id)
  ),
  expense_lr as (
    -- Step 2: floor every share, then hand the leftover oere (R = total oere -
    -- sum of floors, 0 <= R < member count) to the R members with the largest
    -- remainders; ties break on member id ascending (uuid byte order = its
    -- canonical text order), matching the client tie-break. Every expense's
    -- shares now sum EXACTLY to its amount.
    select ec.member_id,
           floor(ec.exact_cents)
             + case when row_number() over (
                      partition by ec.expense_id
                      order by ec.exact_cents - floor(ec.exact_cents) desc, ec.member_id asc
                    ) <= ec.total_cents - sum(floor(ec.exact_cents)) over (partition by ec.expense_id)
                    then 1 else 0 end
             as share_cents
    from expense_cents ec
  ),
  expense_share as (
    select el.member_id,
           sum(el.share_cents) / 100.0 as share
    from expense_lr el
    group by el.member_id
  ),
  expense_paid as (
    select pe.paid_by_member_id as member_id, sum(pe.amount_dkk)::numeric as paid
    from period_expenses pe
    group by pe.paid_by_member_id
  ),
  period_repairs as (
    -- Repairs folded per the workspace mode (GVM-307). Only efter_koersel /
    -- ligeligt fold; deles_ikke (or a null mode) yields no rows. The payer is
    -- paid_by_member_id, falling back to created_by_member_id for pre-108 rows
    -- (GV-269); a repair whose payer is a MEMBER of the ledger — active OR
    -- inactive — is retained (credit-only, GV-274; an inactive payer's cost still
    -- splits over active members and the payer is credited). A repair whose payer
    -- is not a member at all is skipped. Scoped by created_at (timestamps, no
    -- ::date truncation) within the period's [opened_at, closed_at) window.
    select vr.id,
           vr.cost_dkk,
           coalesce(vr.paid_by_member_id, vr.created_by_member_id) as payer_member_id,
           rm.mode
    from public.vehicle_repairs vr
    cross join repairs_mode rm
    cross join period_bounds pb
    join all_members payer on payer.id = coalesce(vr.paid_by_member_id, vr.created_by_member_id)
    where vr.ledger_id = target_ledger_id
      and vr.deleted_at is null
      and vr.cost_dkk > 0
      and rm.mode in ('efter_koersel', 'ligeligt')
      and vr.created_at >= pb.opened_at
      and (pb.closed_at is null or vr.created_at < pb.closed_at)
  ),
  repair_weights as (
    -- efter_koersel weights by each member's raw km (like the expense usage rule);
    -- ligeligt weights everyone equally. Zero total weight (efter_koersel with no
    -- km) falls back to an equal split below, matching the client.
    select pr.id as repair_id,
           pr.cost_dkk,
           am.id as member_id,
           case when pr.mode = 'efter_koersel' then coalesce(mk.km_sum, 0)
                else 1::numeric end as weight
    from period_repairs pr
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  repair_weight_totals as (
    select repair_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from repair_weights
    group by repair_id
  ),
  repair_cents as (
    -- Largest-remainder split for repairs — identical to the expense chain above
    -- (GV-269).
    select rw.repair_id,
           rw.member_id,
           round(rw.cost_dkk * 100) as total_cents,
           round(rw.cost_dkk * 100)
             * (case when rwt.total_weight > 0 then rw.weight else 1 end)
             / (case when rwt.total_weight > 0 then rwt.total_weight else rwt.member_count end)
             as exact_cents
    from repair_weights rw
    join repair_weight_totals rwt using (repair_id)
  ),
  repair_lr as (
    select rc.member_id,
           floor(rc.exact_cents)
             + case when row_number() over (
                      partition by rc.repair_id
                      order by rc.exact_cents - floor(rc.exact_cents) desc, rc.member_id asc
                    ) <= rc.total_cents - sum(floor(rc.exact_cents)) over (partition by rc.repair_id)
                    then 1 else 0 end
             as share_cents
    from repair_cents rc
  ),
  repair_share as (
    select rl.member_id,
           sum(rl.share_cents) / 100.0 as share
    from repair_lr rl
    group by rl.member_id
  ),
  repair_paid as (
    select pr.payer_member_id as member_id, sum(pr.cost_dkk)::numeric as paid
    from period_repairs pr
    group by pr.payer_member_id
  ),
  settlement_members as (
    -- The settlement participant set (GV-274): every ACTIVE member, plus any
    -- member (necessarily inactive, since actives are already in) who PAID fuel,
    -- an expense, or a repair this period. Inactive payers are credit-only — they
    -- appear so they can be credited what they paid, but they carry zero weight in
    -- every share split (the weight CTEs cross join active_members only), so their
    -- net is exactly +paid. An inactive member who paid nothing never appears.
    select am.id, am.name
    from all_members am
    where am.is_active
       or am.id in (select fp.member_id from fuel_paid fp)
       or am.id in (select ep.member_id from expense_paid ep)
       or am.id in (select rp.member_id from repair_paid rp)
  ),
  per_member as (
    select sm.id,
           sm.name,
           round(coalesce(mk.km_sum, 0), 2) as km,
           round(coalesce(f.paid, 0), 2) as fuel_paid,
           round(coalesce(xp.paid, 0), 2) as expense_paid,
           round(coalesce(xs.share, 0), 2) as expense_share,
           round(coalesce(rp.paid, 0), 2) as repair_paid,
           round(coalesce(rs.share, 0), 2) as repair_share
    from settlement_members sm
    left join member_km mk on mk.member_id = sm.id
    left join fuel_paid f on f.member_id = sm.id
    left join expense_paid xp on xp.member_id = sm.id
    left join expense_share xs on xs.member_id = sm.id
    left join repair_paid rp on rp.member_id = sm.id
    left join repair_share rs on rs.member_id = sm.id
  ),
  totals as (
    select coalesce(sum(pm.km), 0) as total_km,
           coalesce(sum(pm.fuel_paid), 0) as total_paid,
           coalesce(sum(pm.expense_paid), 0) as total_expenses,
           coalesce(sum(pm.repair_paid), 0) as total_repairs
    from per_member pm
  )
  select jsonb_build_object(
    'totalKm', t.total_km,
    'totalPaid', t.total_paid,
    'totalExpenses', t.total_expenses,
    'totalRepairs', t.total_repairs,
    'fuelRate', case when t.total_km > 0 then round(t.total_paid / t.total_km, 2) else 0 end,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pm.id,
        'name', pm.name,
        'km', pm.km,
        'fuelPaid', pm.fuel_paid,
        'expensePaid', pm.expense_paid,
        'expenseShare', pm.expense_share,
        'repairPaid', pm.repair_paid,
        'repairShare', pm.repair_share,
        'tripCost', case when t.total_km > 0 then round(pm.km * (t.total_paid / t.total_km), 2) else 0 end,
        'net', case when t.total_km > 0
                    then round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - round(pm.km * (t.total_paid / t.total_km), 2) - pm.expense_share - pm.repair_share, 2)
                    else round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - pm.expense_share - pm.repair_share, 2) end
      ) order by pm.id::text collate "C")
      from per_member pm
    ), '[]'::jsonb)
  )
  into result
  from totals t;

  return result;
end;
$$;

revoke all on function public.calculate_period_settlement(text, uuid) from public;
revoke all on function public.calculate_period_settlement(text, uuid) from anon;
grant execute on function public.calculate_period_settlement(text, uuid) to authenticated;

-- ── GV-275: set_notification_preferences — null-means-unchanged back-compat ──────
-- Re-declared off migration 109 (its newest prior definition). The four advanced
-- params now default NULL = "leave unchanged": each is COALESCEd with the caller's
-- EXISTING row, falling back to the standard defaults (snooze off, quiet disabled
-- 22->7) only when no row exists yet. A trailing clear_snooze_value explicitly
-- clears the snooze (null-means-unchanged makes clearing impossible otherwise). So
-- an old 3-arg client toggling a category can no longer wipe a snooze / quiet-hours
-- setting it never knew about. Validation from 109 is unchanged, run against the
-- EFFECTIVE (coalesced) values. Signature changes (adds clear_snooze_value), so the
-- 7-arg version is dropped and the 8-arg recreated with grants restated in full.
drop function if exists public.set_notification_preferences(boolean, boolean, boolean, timestamptz, boolean, smallint, smallint);
create function public.set_notification_preferences(
  activity boolean,
  payments boolean,
  periods boolean,
  snooze_until_value timestamptz default null,
  quiet_hours_enabled_value boolean default null,
  quiet_start_hour_value smallint default null,
  quiet_end_hour_value smallint default null,
  clear_snooze_value boolean default false
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_existing public.notification_preferences%rowtype;
  v_snooze timestamptz;
  v_quiet_enabled boolean;
  v_quiet_start smallint;
  v_quiet_end smallint;
begin
  if v_uid is null then
    raise exception 'Notification preferences require a signed-in user' using errcode = '42501';
  end if;

  select * into v_existing
  from public.notification_preferences
  where user_id = v_uid;

  -- Effective advanced values: a null param leaves the existing row value
  -- unchanged (or the standard default when no row exists). clear_snooze_value
  -- wins over any snooze param and sets snooze_until back to null (GV-275).
  if coalesce(clear_snooze_value, false) then
    v_snooze := null;
  else
    v_snooze := coalesce(snooze_until_value, v_existing.snooze_until);
  end if;
  v_quiet_enabled := coalesce(quiet_hours_enabled_value, v_existing.quiet_hours_enabled, false);
  v_quiet_start := coalesce(quiet_start_hour_value, v_existing.quiet_start_hour, 22::smallint);
  v_quiet_end := coalesce(quiet_end_hour_value, v_existing.quiet_end_hour, 7::smallint);

  -- Validation from migration 109, unchanged, on the effective values.
  if v_quiet_start is null or v_quiet_start < 0 or v_quiet_start > 23 then
    raise exception 'quiet_start_hour must be between 0 and 23' using errcode = '22023';
  end if;
  if v_quiet_end is null or v_quiet_end < 0 or v_quiet_end > 23 then
    raise exception 'quiet_end_hour must be between 0 and 23' using errcode = '22023';
  end if;
  if coalesce(v_quiet_enabled, false) and v_quiet_start = v_quiet_end then
    raise exception 'quiet hours start and end must differ when enabled' using errcode = '22023';
  end if;
  if v_snooze is not null
     and (v_snooze <= now() - interval '1 minute'
          or v_snooze > now() + interval '30 days') then
    raise exception 'snooze_until must be in the future and at most 30 days out' using errcode = '22023';
  end if;

  insert into public.notification_preferences (
    user_id, activity_enabled, payments_enabled, periods_enabled,
    snooze_until, quiet_hours_enabled, quiet_start_hour, quiet_end_hour, updated_at
  )
  values (
    v_uid,
    coalesce(activity, true),
    coalesce(payments, true),
    coalesce(periods, true),
    v_snooze,
    coalesce(v_quiet_enabled, false),
    v_quiet_start,
    v_quiet_end,
    now()
  )
  on conflict (user_id) do update
  set activity_enabled = excluded.activity_enabled,
      payments_enabled = excluded.payments_enabled,
      periods_enabled = excluded.periods_enabled,
      snooze_until = excluded.snooze_until,
      quiet_hours_enabled = excluded.quiet_hours_enabled,
      quiet_start_hour = excluded.quiet_start_hour,
      quiet_end_hour = excluded.quiet_end_hour,
      updated_at = now();
end;
$$;

revoke all on function public.set_notification_preferences(boolean, boolean, boolean, timestamptz, boolean, smallint, smallint, boolean) from public;
grant execute on function public.set_notification_preferences(boolean, boolean, boolean, timestamptz, boolean, smallint, smallint, boolean) to authenticated;

-- ── GV-274: repair-aware close-staleness fingerprint ────────────────────────────
-- Re-declared off migration 070 (its newest prior definition; 083 only re-granted
-- it). Since GVM-307/108 folded repairs into the settlement, a repair added or
-- removed while a close is being prepared changes the computed settlement — but the
-- close-staleness fingerprint only covered trips/fuel/expenses, and the totals guard
-- only checks totalKm/totalPaid (repairs move neither). So a stale snapshot could
-- close over a changed repair set. This adds repairs to the fingerprint, scoped by
-- created_at within the period's [opened_at, closed_at) window (deleted_at null) —
-- identical to how calculate_period_settlement and the mobile client
-- (scopeRepairsToPeriod) scope them. The "repairs" key is appended ONLY when the
-- period has at least one in-scope repair, so a period with no repairs produces the
-- byte-identical trips/fuel/expenses string as before (and matches the mobile
-- client's periodEntryFingerprint, which likewise omits the key when empty).
create or replace function public.calculate_period_entry_fingerprint(
  target_ledger_id text,
  target_period_id uuid
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result text;
  repairs_json text;
begin
  if not public.is_operator_context()
     and not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can calculate the entry fingerprint' using errcode = '42501';
  end if;

  -- Repairs have no period_id: a repair belongs to the period whose
  -- [opened_at, closed_at) window contains its created_at (the moment it was
  -- LOGGED), exactly as calculate_period_settlement scopes them (GV-269). During a
  -- close the period is still open (closed_at null), so the window has no upper
  -- bound. Empty string when the period has no in-scope repair.
  select coalesce(
           string_agg(to_json(vr.id::text)::text, ',' order by vr.id::text collate "C"),
           '')
    into repairs_json
    from public.vehicle_repairs vr
    cross join public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
      and vr.ledger_id = target_ledger_id
      and vr.deleted_at is null
      and vr.created_at >= sp.opened_at
      and (sp.closed_at is null or vr.created_at < sp.closed_at);

  select '{"trips":['
    || coalesce((
         select string_agg(to_json(t.id::text)::text, ',' order by t.id::text collate "C")
         from public.trips t
         where t.ledger_id = target_ledger_id
           and t.period_id = target_period_id
           and t.deleted_at is null
       ), '')
    || '],"fuel":['
    || coalesce((
         select string_agg(to_json(fp.id::text)::text, ',' order by fp.id::text collate "C")
         from public.fuel_payments fp
         where fp.ledger_id = target_ledger_id
           and fp.period_id = target_period_id
           and fp.deleted_at is null
       ), '')
    || '],"expenses":['
    || coalesce((
         select string_agg(to_json(we.id::text)::text, ',' order by we.id::text collate "C")
         from public.workspace_expenses we
         where we.ledger_id = target_ledger_id
           and we.period_id = target_period_id
           and we.deleted_at is null
       ), '')
    || ']'
    || case when repairs_json <> '' then ',"repairs":[' || repairs_json || ']' else '' end
    || '}'
  into result;

  return result;
end;
$$;

revoke all on function public.calculate_period_entry_fingerprint(text, uuid) from public;
revoke all on function public.calculate_period_entry_fingerprint(text, uuid) from anon;
grant execute on function public.calculate_period_entry_fingerprint(text, uuid) to authenticated;

-- ── Register migration ────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('112_release_blockers_remediation',
        'Codex release-blocker remediation (GV-273/274/275). GV-273: enforce_repair_period_lock trigger freezes a vehicle_repairs row (UPDATE incl. soft delete, and DELETE) once its created_at falls inside a closed settlement period (errcode 22023, mirrors the GV-199 closed-period rejection). GV-274: upsert_recurring_expense (off 077) requires amount > 0 and next_due_date within [today-90d, today+5y]; both recurring generators (client off 075, scheduler off 110) cap catch-up at 24 occurrences/template/run and advance next_due_date only through what was generated; the scheduler scan now requires an open period to EXIST and orders by oldest due next_due_date; calculate_period_settlement (off 108) makes an INACTIVE payer a credit-only participant — credited what they paid with zero share weight, cost still split over active members, net = +paid, applied to expenses, repairs, and fuel consistently; calculate_period_entry_fingerprint (off 070) is now repair-aware (repairs scoped by created_at, key omitted when empty) so a close over a changed repair set is caught. GV-275: set_notification_preferences (off 109) advanced params default NULL = leave-unchanged (coalesce with existing row) plus a clear_snooze_value to explicitly clear the snooze, so old 3-arg clients no longer reset snooze/quiet hours.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ═══════════════════════════════════════════════════════════════════════════
-- Verbatim from 113_close_reminder_running_mode.sql (GVM-318). Function body
-- below is byte-identical to the migration (schema-equivalence guard).
-- ═══════════════════════════════════════════════════════════════════════════

-- ── claim_due_close_reminders: skip running-mode groups (GVM-318 / GVM-64) ───────────
create or replace function public.claim_due_close_reminders(
  batch_limit integer default 200
)
returns table (period_id uuid, ledger_id text, label text, admin_emails text[], claim_token uuid)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select sp.id
    from public.settlement_periods sp
    join public.ledgers l on l.id = sp.ledger_id
    where sp.status = 'open'
      and l.close_reminder_enabled = true
      and l.settlement_mode = 'monthly'
      and sp.opened_at <= now() - interval '30 days'
      and (sp.close_reminder_claimed_at is null
           or sp.close_reminder_claimed_at <= now() - interval '15 minutes')
      and (sp.last_close_reminder_at is null
           or sp.last_close_reminder_at <= now() - interval '7 days')
    order by sp.opened_at
    limit greatest(coalesce(batch_limit, 200), 0)
    for update of sp skip locked
  ),
  claimed as (
    update public.settlement_periods sp
    set close_reminder_claimed_at = now(),
        close_reminder_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where sp.id = t.id
    returning sp.id as period_id,
              sp.ledger_id as ledger_id,
              sp.label as label,
              sp.close_reminder_claim_token as claim_token
  )
  select c.period_id,
         c.ledger_id,
         c.label,
         coalesce(
           array_agg(lower(lm.email)) filter (where lm.email is not null),
           array[]::text[]
         ) as admin_emails,
         c.claim_token
  from claimed c
  left join public.ledger_members lm
    on lm.ledger_id = c.ledger_id
   and lm.role = 'admin'
   and lm.is_active = true
   and lm.email is not null
  group by c.period_id, c.ledger_id, c.label, c.claim_token;
end;
$$;

revoke all on function public.claim_due_close_reminders(integer) from public;
revoke all on function public.claim_due_close_reminders(integer) from anon;
revoke all on function public.claim_due_close_reminders(integer) from authenticated;
grant execute on function public.claim_due_close_reminders(integer) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('113_close_reminder_running_mode',
        'Close-period reminder skips running-mode groups (GVM-318): claim_due_close_reminders re-declared off 106; the target CTE additionally requires ledgers.settlement_mode = ''monthly'' so a group that switched to Løbende never receives the 30-day cadence "luk perioden" push even when close_reminder_enabled is still true. Honours the locked GVM-64 running-mode suppression (in-app close-nudge already suppresses the cadence trigger in running mode). Signature, grants (service_role only), and lease/claim-token semantics unchanged.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();


-- Migration 114: repair↔period binding + payer-deactivation recurring suspension (GV-277)
--
-- Two Codex 2026-07-12 hardening items for repairs and recurring templates:
--
--   A) Repair/close race. Repairs had NO period_id — every consumer scoped them
--      to a period by created_at (calculate_period_settlement 112, the entry
--      fingerprint 112, the enforce_repair_period_lock trigger 112). A repair
--      logged in the same instant a close runs could therefore be scoped
--      ambiguously (the settlement and the fingerprint each recompute the set
--      independently). This binds a repair to its period AT INSERT:
--        * vehicle_repairs.period_id (nullable FK, on delete set null) is added.
--        * insert_repair (off 108) takes the SAME ledger advisory lock the close
--          uses — the BLOCKING variant pg_advisory_xact_lock(hashtext(ledger_id))
--          so a repair insert QUEUES behind an in-flight close (which holds the
--          lock via pg_try_advisory_xact_lock and would reject a concurrent writer
--          otherwise), then resolves the ledger's open period and stamps period_id.
--          A repair therefore lands in exactly the period that was open when it was
--          logged, never straddling a close.
--        * calculate_period_settlement (off 112) and calculate_period_entry_fingerprint
--          (off 112) scope repairs by period_id, falling back to the 112 created_at
--          window ONLY for legacy null-period rows (pre-114). For a stamped row the
--          two agree by construction (created_at is inside the period that was open
--          at insert), so the client — which still scopes by created_at
--          (scopeRepairsToPeriod) — stays in lockstep with the server.
--        * close_settlement_period (off 104) stamps period_id on the closing
--          period's remaining legacy null-period repairs BEFORE it flips the period
--          to closed (so enforce_repair_period_lock still permits the write), making
--          period_id authoritative for every repair once a period is closed.
--        * The entry fingerprint's repair component becomes id+amount PAIRS
--          (["<id>",<oere>]) instead of bare ids — a financial revision, so editing
--          a repair's COST now busts a prepared close (repairs move neither totalKm
--          nor totalPaid, so the amount guard never caught a repair-cost edit). oere
--          integers serialise byte-identically in Postgres and JS; the client
--          (src/lib/period-snapshot.ts, GVM PR) mirrors the exact format. The
--          "repairs" key is still omitted when the period has no in-scope repair, so
--          a repair-free period keeps its pre-114 trips/fuel/expenses string.
--
--   B) Recurring templates on payer deactivation. Deactivating a member left their
--      recurring-expense templates active, so the generators kept materialising
--      expenses charged to an inactive payer (credit-only in the settlement since
--      112) — silently distorting balances. set_ledger_member_active_admin (off 012)
--      now, on deactivation, suspends (is_active = false) every recurring template
--      the member pays for and writes a 'recurring_suspended' ledger_events row (in
--      Danish, naming the templates) so admins get an action item to reassign the
--      payer or delete the template. Both generators (off 112) additionally guard
--      payer activity — they skip a template whose payer is a known inactive member
--      — as defense in depth (member_is_active_in_ledger returns true for a null
--      payer, so legacy null-payer templates are unaffected).
--
-- Every re-declared function is based on its NEWEST prior definition, verified by
-- grepping every migration: insert_repair 108, calculate_period_settlement 112,
-- calculate_period_entry_fingerprint 112, close_settlement_period 104,
-- set_ledger_member_active_admin 012, both generators 112.

-- ── A.1: repair → period binding column ─────────────────────────────────────────
-- Nullable so pre-114 rows keep a null period_id (scoped by created_at until a
-- close stamps them). on delete set null so dropping a period never deletes repair
-- history — the created_at fallback then re-scopes the row.
alter table public.vehicle_repairs
  add column if not exists period_id uuid references public.settlement_periods(id) on delete set null;

-- ── A.2: insert_repair — ledger advisory lock + period_id stamp ──────────────────
-- Re-declared off migration 108 (its newest prior definition). The validation,
-- payer resolution and grants are 108 verbatim; the only additions (GV-277) are the
-- blocking ledger advisory lock (shared with close_settlement_period so a repair
-- insert and a close can never interleave) and resolving + stamping the open
-- period's id. Signature is unchanged, so this is a plain create-or-replace.
create or replace function public.insert_repair(
  target_ledger_id text,
  repair_date_value date,
  description_value text,
  cost_dkk_value numeric,
  odo_km_value integer default null,
  workshop text default null,
  paid_by_member_id_value uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  resolved_payer_member_id uuid;
  resolved_period_id uuid;
  clean_description text;
  clean_workshop text;
  result_id uuid;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can log repairs' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  clean_description := nullif(btrim(description_value), '');
  if clean_description is null then
    raise exception 'Repair description is required' using errcode = '22023';
  end if;
  if length(clean_description) > 500 then
    raise exception 'Repair description must be 500 characters or fewer' using errcode = '22023';
  end if;

  -- Repairs are financial records (GVM-307 folds them into the settlement), so a
  -- missing or non-positive cost is rejected rather than coalesced to 0.
  if cost_dkk_value is null or cost_dkk_value <= 0 then
    raise exception 'Repair cost must be greater than zero' using errcode = '22023';
  end if;

  if odo_km_value is not null and odo_km_value < 0 then
    raise exception 'Odometer reading cannot be negative' using errcode = '22023';
  end if;

  if repair_date_value is not null
     and (repair_date_value < date '2000-01-01'
          or repair_date_value > current_date + interval '1 year') then
    raise exception 'Repair date is out of range' using errcode = '22023';
  end if;

  clean_workshop := nullif(btrim(workshop), '');
  if clean_workshop is not null and length(clean_workshop) > 120 then
    raise exception 'Workshop name must be 120 characters or fewer' using errcode = '22023';
  end if;

  -- Payer: null means the actor paid. A named payer must be an ACTIVE member of
  -- THIS workspace — an inactive or foreign member is rejected, mirroring how the
  -- settlement skips repairs whose payer is not active.
  if paid_by_member_id_value is not null then
    if not exists (
      select 1
      from public.ledger_members lm
      where lm.id = paid_by_member_id_value
        and lm.ledger_id = target_ledger_id
        and lm.is_active = true
    ) then
      raise exception 'Payer must be an active member of this workspace' using errcode = '22023';
    end if;
  end if;
  resolved_payer_member_id := coalesce(paid_by_member_id_value, actor_member_id);

  -- GV-277: take the SAME ledger advisory lock close_settlement_period uses. The
  -- BLOCKING variant queues this insert behind an in-flight close (which holds the
  -- lock and rejects concurrent writers via its own pg_try_advisory_xact_lock), so a
  -- repair can never be logged into a period mid-close. The lock is re-entrant
  -- within a transaction, so an RPC that already holds it (or a later close in the
  -- same txn) is unaffected. Then stamp the id of the ledger's currently OPEN period
  -- (if any) so the repair is bound to exactly the period that was open when it was
  -- logged; a null (no open period, e.g. the brief post-close gap) falls back to the
  -- created_at scoping in the settlement/fingerprint.
  perform pg_advisory_xact_lock(hashtext(target_ledger_id));

  select sp.id
    into resolved_period_id
    from public.settlement_periods sp
    where sp.ledger_id = target_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    order by sp.opened_at desc
    limit 1;

  insert into public.vehicle_repairs (
    ledger_id, repair_date, description, cost_dkk, odo_km, workshop,
    created_by_member_id, paid_by_member_id, period_id
  ) values (
    target_ledger_id,
    coalesce(repair_date_value, current_date),
    clean_description,
    round(cost_dkk_value, 2),
    odo_km_value,
    clean_workshop,
    actor_member_id,
    resolved_payer_member_id,
    resolved_period_id
  )
  returning id into result_id;

  return jsonb_build_object('id', result_id);
end;
$$;

revoke all on function public.insert_repair(text, date, text, numeric, integer, text, uuid) from public;
revoke all on function public.insert_repair(text, date, text, numeric, integer, text, uuid) from anon;
grant execute on function public.insert_repair(text, date, text, numeric, integer, text, uuid) to authenticated;

-- ── A.3: calculate_period_settlement — repair scoping by period_id ──────────────
-- Re-declared off migration 112 (its newest prior definition). Everything — the
-- trips/fuel maths, the largest-remainder splits, and the credit-only inactive
-- payer rule — is 112 verbatim. The ONLY change (GV-277) is the period_repairs
-- scope predicate: a repair belongs to this period when vr.period_id equals it, or
-- (legacy null-period rows only) when its created_at falls in the period's
-- [opened_at, closed_at) window. Signature unchanged; grants restated.
create or replace function public.calculate_period_settlement(
  target_ledger_id text,
  target_period_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_operator_context()
     and not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can calculate settlements' using errcode = '42501';
  end if;

  with active_members as (
    select lm.id, lm.name
    from public.ledger_members lm
    where lm.ledger_id = target_ledger_id
      and lm.is_active = true
  ),
  all_members as (
    -- Every member of the ledger, active or not. Used to retain (not drop) an
    -- entry whose payer has since gone inactive so that payer can be credited
    -- (GV-274, credit-only). is_active decides who lands in settlement_members.
    select lm.id, lm.name, lm.is_active
    from public.ledger_members lm
    where lm.ledger_id = target_ledger_id
  ),
  live_trips as (
    select t.id,
           t.driver_member_id,
           greatest(t.end_km - t.start_km, 0)::numeric as km
    from public.trips t
    where t.ledger_id = target_ledger_id
      and t.period_id = target_period_id
      and t.deleted_at is null
  ),
  trip_assignees as (
    select lt.id as trip_id,
           lt.km,
           coalesce(
             valid_participants.member_ids,
             case when driver_check.id is not null then array[lt.driver_member_id] end
           ) as assignees
    from live_trips lt
    left join lateral (
      select array_agg(distinct tp.member_id) as member_ids
      from public.trip_participants tp
      join active_members am on am.id = tp.member_id
      where tp.trip_id = lt.id
    ) valid_participants on true
    left join active_members driver_check on driver_check.id = lt.driver_member_id
  ),
  km_shares as (
    select shared.member_id,
           ta.km / array_length(ta.assignees, 1) as share_km
    from trip_assignees ta
    cross join lateral unnest(ta.assignees) as shared(member_id)
    where ta.assignees is not null
      and array_length(ta.assignees, 1) > 0
  ),
  member_km as (
    -- Unrounded per-member km, reused both for the settlement km and as the
    -- usage-split weight (the client weights usage on raw km).
    select ks.member_id, sum(ks.share_km) as km_sum
    from km_shares ks
    group by ks.member_id
  ),
  fuel_paid as (
    select fp.payer_member_id as member_id,
           sum(fp.amount)::numeric as paid
    from public.fuel_payments fp
    where fp.ledger_id = target_ledger_id
      and fp.period_id = target_period_id
      and fp.deleted_at is null
      and fp.payer_member_id is not null
    group by fp.payer_member_id
  ),
  ledger_defaults as (
    select l.expense_split_defaults as defaults
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  repairs_mode as (
    -- The workspace rule that governs repair folding (GVM-307). null (old row,
    -- pre-107) behaves like deles_ikke: the mode filter below excludes every
    -- repair, matching a client that has no mode field to read.
    select l.repairs_split_mode as mode
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  period_bounds as (
    -- Legacy null-period repairs (pre-114) have no period_id: such a repair counts
    -- in the period whose [opened_at, closed_at) window contains its created_at —
    -- the moment it was LOGGED (GV-269; repair_date is display-only). A stamped
    -- repair (GV-277) is matched by period_id instead and never needs this window.
    -- The settling period is still open here (closed_at null), so its window has no
    -- upper bound.
    select sp.opened_at, sp.closed_at
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
  ),
  period_expenses as (
    -- Live expenses in this period whose payer is a MEMBER of the ledger (active
    -- OR inactive). An inactive payer is retained (credit-only, GV-274) rather
    -- than dropped: its cost is still split (over active members, via the weight
    -- CTEs below), and the payer is credited what they paid. An expense with no
    -- payer or a non-member payer is still skipped entirely.
    select we.id,
           we.amount_dkk,
           we.paid_by_member_id,
           we.split_config,
           coalesce(nullif(we.split_rule, ''),
                    (ld.defaults ->> we.category),
                    'equal') as rule
    from public.workspace_expenses we
    cross join ledger_defaults ld
    join all_members payer on payer.id = we.paid_by_member_id
    where we.ledger_id = target_ledger_id
      and we.period_id = target_period_id
      and we.deleted_at is null
      and we.amount_dkk > 0
  ),
  expense_weights as (
    select pe.id as expense_id,
           pe.amount_dkk,
           am.id as member_id,
           case pe.rule
             when 'usage'  then coalesce(mk.km_sum, 0)
             when 'custom' then coalesce((pe.split_config ->> am.id::text)::numeric, 0)
             else 1::numeric
           end as weight
    from period_expenses pe
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  expense_weight_totals as (
    select expense_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from expense_weights
    group by expense_id
  ),
  expense_cents as (
    -- Largest-remainder split, step 1 (GV-269): per expense, work in integer
    -- oere and compute each member's exact (unrounded) share of them. A
    -- non-positive total weight falls back to equal weights, matching the
    -- pre-108 fallback and the client.
    select ew.expense_id,
           ew.member_id,
           round(ew.amount_dkk * 100) as total_cents,
           round(ew.amount_dkk * 100)
             * (case when ewt.total_weight > 0 then ew.weight else 1 end)
             / (case when ewt.total_weight > 0 then ewt.total_weight else ewt.member_count end)
             as exact_cents
    from expense_weights ew
    join expense_weight_totals ewt using (expense_id)
  ),
  expense_lr as (
    -- Step 2: floor every share, then hand the leftover oere (R = total oere -
    -- sum of floors, 0 <= R < member count) to the R members with the largest
    -- remainders; ties break on member id ascending (uuid byte order = its
    -- canonical text order), matching the client tie-break. Every expense's
    -- shares now sum EXACTLY to its amount.
    select ec.member_id,
           floor(ec.exact_cents)
             + case when row_number() over (
                      partition by ec.expense_id
                      order by ec.exact_cents - floor(ec.exact_cents) desc, ec.member_id asc
                    ) <= ec.total_cents - sum(floor(ec.exact_cents)) over (partition by ec.expense_id)
                    then 1 else 0 end
             as share_cents
    from expense_cents ec
  ),
  expense_share as (
    select el.member_id,
           sum(el.share_cents) / 100.0 as share
    from expense_lr el
    group by el.member_id
  ),
  expense_paid as (
    select pe.paid_by_member_id as member_id, sum(pe.amount_dkk)::numeric as paid
    from period_expenses pe
    group by pe.paid_by_member_id
  ),
  period_repairs as (
    -- Repairs folded per the workspace mode (GVM-307). Only efter_koersel /
    -- ligeligt fold; deles_ikke (or a null mode) yields no rows. The payer is
    -- paid_by_member_id, falling back to created_by_member_id for pre-108 rows
    -- (GV-269); a repair whose payer is a MEMBER of the ledger — active OR
    -- inactive — is retained (credit-only, GV-274). Scoped by period_id (GV-277):
    -- a stamped repair matches vr.period_id = target_period_id; a legacy
    -- null-period repair falls back to created_at within the period's
    -- [opened_at, closed_at) window (timestamps, no ::date truncation).
    select vr.id,
           vr.cost_dkk,
           coalesce(vr.paid_by_member_id, vr.created_by_member_id) as payer_member_id,
           rm.mode
    from public.vehicle_repairs vr
    cross join repairs_mode rm
    cross join period_bounds pb
    join all_members payer on payer.id = coalesce(vr.paid_by_member_id, vr.created_by_member_id)
    where vr.ledger_id = target_ledger_id
      and vr.deleted_at is null
      and vr.cost_dkk > 0
      and rm.mode in ('efter_koersel', 'ligeligt')
      and (
        vr.period_id = target_period_id
        or (vr.period_id is null
            and vr.created_at >= pb.opened_at
            and (pb.closed_at is null or vr.created_at < pb.closed_at))
      )
  ),
  repair_weights as (
    -- efter_koersel weights by each member's raw km (like the expense usage rule);
    -- ligeligt weights everyone equally. Zero total weight (efter_koersel with no
    -- km) falls back to an equal split below, matching the client.
    select pr.id as repair_id,
           pr.cost_dkk,
           am.id as member_id,
           case when pr.mode = 'efter_koersel' then coalesce(mk.km_sum, 0)
                else 1::numeric end as weight
    from period_repairs pr
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  repair_weight_totals as (
    select repair_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from repair_weights
    group by repair_id
  ),
  repair_cents as (
    -- Largest-remainder split for repairs — identical to the expense chain above
    -- (GV-269).
    select rw.repair_id,
           rw.member_id,
           round(rw.cost_dkk * 100) as total_cents,
           round(rw.cost_dkk * 100)
             * (case when rwt.total_weight > 0 then rw.weight else 1 end)
             / (case when rwt.total_weight > 0 then rwt.total_weight else rwt.member_count end)
             as exact_cents
    from repair_weights rw
    join repair_weight_totals rwt using (repair_id)
  ),
  repair_lr as (
    select rc.member_id,
           floor(rc.exact_cents)
             + case when row_number() over (
                      partition by rc.repair_id
                      order by rc.exact_cents - floor(rc.exact_cents) desc, rc.member_id asc
                    ) <= rc.total_cents - sum(floor(rc.exact_cents)) over (partition by rc.repair_id)
                    then 1 else 0 end
             as share_cents
    from repair_cents rc
  ),
  repair_share as (
    select rl.member_id,
           sum(rl.share_cents) / 100.0 as share
    from repair_lr rl
    group by rl.member_id
  ),
  repair_paid as (
    select pr.payer_member_id as member_id, sum(pr.cost_dkk)::numeric as paid
    from period_repairs pr
    group by pr.payer_member_id
  ),
  settlement_members as (
    -- The settlement participant set (GV-274): every ACTIVE member, plus any
    -- member (necessarily inactive, since actives are already in) who PAID fuel,
    -- an expense, or a repair this period. Inactive payers are credit-only — they
    -- appear so they can be credited what they paid, but they carry zero weight in
    -- every share split (the weight CTEs cross join active_members only), so their
    -- net is exactly +paid. An inactive member who paid nothing never appears.
    select am.id, am.name
    from all_members am
    where am.is_active
       or am.id in (select fp.member_id from fuel_paid fp)
       or am.id in (select ep.member_id from expense_paid ep)
       or am.id in (select rp.member_id from repair_paid rp)
  ),
  per_member as (
    select sm.id,
           sm.name,
           round(coalesce(mk.km_sum, 0), 2) as km,
           round(coalesce(f.paid, 0), 2) as fuel_paid,
           round(coalesce(xp.paid, 0), 2) as expense_paid,
           round(coalesce(xs.share, 0), 2) as expense_share,
           round(coalesce(rp.paid, 0), 2) as repair_paid,
           round(coalesce(rs.share, 0), 2) as repair_share
    from settlement_members sm
    left join member_km mk on mk.member_id = sm.id
    left join fuel_paid f on f.member_id = sm.id
    left join expense_paid xp on xp.member_id = sm.id
    left join expense_share xs on xs.member_id = sm.id
    left join repair_paid rp on rp.member_id = sm.id
    left join repair_share rs on rs.member_id = sm.id
  ),
  totals as (
    select coalesce(sum(pm.km), 0) as total_km,
           coalesce(sum(pm.fuel_paid), 0) as total_paid,
           coalesce(sum(pm.expense_paid), 0) as total_expenses,
           coalesce(sum(pm.repair_paid), 0) as total_repairs
    from per_member pm
  )
  select jsonb_build_object(
    'totalKm', t.total_km,
    'totalPaid', t.total_paid,
    'totalExpenses', t.total_expenses,
    'totalRepairs', t.total_repairs,
    'fuelRate', case when t.total_km > 0 then round(t.total_paid / t.total_km, 2) else 0 end,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pm.id,
        'name', pm.name,
        'km', pm.km,
        'fuelPaid', pm.fuel_paid,
        'expensePaid', pm.expense_paid,
        'expenseShare', pm.expense_share,
        'repairPaid', pm.repair_paid,
        'repairShare', pm.repair_share,
        'tripCost', case when t.total_km > 0 then round(pm.km * (t.total_paid / t.total_km), 2) else 0 end,
        'net', case when t.total_km > 0
                    then round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - round(pm.km * (t.total_paid / t.total_km), 2) - pm.expense_share - pm.repair_share, 2)
                    else round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - pm.expense_share - pm.repair_share, 2) end
      ) order by pm.id::text collate "C")
      from per_member pm
    ), '[]'::jsonb)
  )
  into result
  from totals t;

  return result;
end;
$$;

revoke all on function public.calculate_period_settlement(text, uuid) from public;
revoke all on function public.calculate_period_settlement(text, uuid) from anon;
grant execute on function public.calculate_period_settlement(text, uuid) to authenticated;

-- ── A.4: calculate_period_entry_fingerprint — period_id scope + id+amount pairs ──
-- Re-declared off migration 112 (its newest prior definition). Trips/fuel/expenses
-- are 112 verbatim. Two GV-277 changes to the repair component: (1) scope by
-- period_id, falling back to the 112 created_at window for legacy null-period rows;
-- (2) emit id+amount PAIRS (["<id>",<oere>]) instead of bare ids so a repair-cost
-- edit — which moves neither totalKm nor totalPaid, and so slips the amount guard —
-- busts a prepared close. oere integers (round(cost*100)) serialise byte-identically
-- in Postgres and JS; the client (periodEntryFingerprint) mirrors the exact format.
-- The "repairs" key is still omitted when the period has no in-scope repair, so a
-- repair-free period keeps its pre-114 trips/fuel/expenses string.
create or replace function public.calculate_period_entry_fingerprint(
  target_ledger_id text,
  target_period_id uuid
)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result text;
  repairs_json text;
begin
  if not public.is_operator_context()
     and not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can calculate the entry fingerprint' using errcode = '42501';
  end if;

  -- Repairs are scoped by period_id (GV-277); a legacy null-period row (pre-114)
  -- falls back to created_at within the period's [opened_at, closed_at) window,
  -- exactly as calculate_period_settlement scopes them. During a close the period is
  -- still open (closed_at null), so the window has no upper bound. Each repair is
  -- emitted as an ["<id>",<oere>] pair so a cost edit changes the fingerprint; the
  -- empty string yields no "repairs" key below.
  select coalesce(
           string_agg(
             '[' || to_json(vr.id::text)::text || ',' || round(vr.cost_dkk * 100)::bigint::text || ']',
             ',' order by vr.id::text collate "C"),
           '')
    into repairs_json
    from public.vehicle_repairs vr
    cross join public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
      and vr.ledger_id = target_ledger_id
      and vr.deleted_at is null
      and (
        vr.period_id = target_period_id
        or (vr.period_id is null
            and vr.created_at >= sp.opened_at
            and (sp.closed_at is null or vr.created_at < sp.closed_at))
      );

  select '{"trips":['
    || coalesce((
         select string_agg(to_json(t.id::text)::text, ',' order by t.id::text collate "C")
         from public.trips t
         where t.ledger_id = target_ledger_id
           and t.period_id = target_period_id
           and t.deleted_at is null
       ), '')
    || '],"fuel":['
    || coalesce((
         select string_agg(to_json(fp.id::text)::text, ',' order by fp.id::text collate "C")
         from public.fuel_payments fp
         where fp.ledger_id = target_ledger_id
           and fp.period_id = target_period_id
           and fp.deleted_at is null
       ), '')
    || '],"expenses":['
    || coalesce((
         select string_agg(to_json(we.id::text)::text, ',' order by we.id::text collate "C")
         from public.workspace_expenses we
         where we.ledger_id = target_ledger_id
           and we.period_id = target_period_id
           and we.deleted_at is null
       ), '')
    || ']'
    || case when repairs_json <> '' then ',"repairs":[' || repairs_json || ']' else '' end
    || '}'
  into result;

  return result;
end;
$$;

revoke all on function public.calculate_period_entry_fingerprint(text, uuid) from public;
revoke all on function public.calculate_period_entry_fingerprint(text, uuid) from anon;
grant execute on function public.calculate_period_entry_fingerprint(text, uuid) to authenticated;

-- ── A.5: close_settlement_period — stamp legacy repairs before closing ──────────
-- Re-declared off migration 104 (its newest prior definition). The integrity gate,
-- require-requests coverage, duplicate guard, close/open and event are 104 verbatim.
-- The only GV-277 addition is one UPDATE: while the period is still OPEN (so
-- enforce_repair_period_lock permits the write), stamp period_id = target_period_id
-- on the period's remaining legacy null-period repairs (matched by the same
-- created_at window the settlement/fingerprint use), so period_id is authoritative
-- for every repair once the period is closed. New repairs already carry period_id
-- (insert_repair, under the same advisory lock this RPC holds). Signature and grants
-- unchanged.
create or replace function public.close_settlement_period(
  target_ledger_id text,
  target_period_id uuid,
  period_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  snapshot_fingerprint text;
  server_fingerprint text;
  computed jsonb;
  computed_person jsonb;
  snapshot_person jsonb;
  snapshot_flow numeric;
  duplicate_period_id uuid;
  closed_period_id uuid;
  new_open_period_id uuid;
  requested_closed_at timestamptz;
  lock_acquired boolean;
  v_rule_require_requests boolean;
  v_settlement jsonb;
  v_missing_settlements integer := 0;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing open settlement period id' using errcode = '22023';
  end if;

  if period_snapshot is null or jsonb_typeof(period_snapshot) <> 'object' then
    raise exception 'Period snapshot must be a JSON object' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can close settlement periods' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- Guard before taking the advisory lock. Older frontend builds and health probes
  -- may call this RPC with a fake or already-closed period id. Reject those
  -- immediately so they cannot queue behind the lock and burn database CPU.
  if not exists (
    select 1
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
  ) then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '22023';
  end if;

  lock_acquired := pg_try_advisory_xact_lock(hashtext(target_ledger_id));
  if lock_acquired is not true then
    raise exception 'Another settlement close is already in progress for this ledger' using errcode = '55P03';
  end if;

  -- ── Integrity gate (GVM-112) ──────────────────────────────────────────────
  -- (a) Entry set: the snapshot's fingerprint must equal the one recomputed
  -- from the live rows. In-flight writers hold FOR SHARE on the period row, so
  -- by the time this runs the row set is stable for the transaction.
  snapshot_fingerprint := nullif(period_snapshot->>'entryFingerprint', '');
  server_fingerprint := public.calculate_period_entry_fingerprint(target_ledger_id, target_period_id);

  if snapshot_fingerprint is not null and snapshot_fingerprint <> server_fingerprint then
    raise exception 'Entries changed since this close was prepared. Refresh the app and try closing again.'
      using errcode = '23514';
  end if;

  -- (b) Amounts: per-member figures within 0.02 kr, totals within 0.05 kr.
  computed := public.calculate_period_settlement(target_ledger_id, target_period_id);

  if abs(coalesce((period_snapshot->>'totalKm')::numeric, 0) - (computed->>'totalKm')::numeric) > 0.05
     or abs(coalesce((period_snapshot->>'totalPaid')::numeric, 0) - (computed->>'totalPaid')::numeric) > 0.05 then
    raise exception 'Snapshot totals do not match the server calculation. Refresh the app and try closing again.'
      using errcode = '23514';
  end if;

  for computed_person in
    select value from jsonb_array_elements(computed->'people')
  loop
    select p.value
      into snapshot_person
      from jsonb_array_elements(coalesce(period_snapshot->'people', '[]'::jsonb)) as p(value)
      where p.value->>'id' = computed_person->>'id'
      limit 1;

    if abs(coalesce((snapshot_person->>'km')::numeric, 0) - (computed_person->>'km')::numeric) > 0.02
       or abs(coalesce((snapshot_person->>'fuelPaid')::numeric, 0) - (computed_person->>'fuelPaid')::numeric) > 0.02
       or abs(coalesce((snapshot_person->>'net')::numeric, 0) - (computed_person->>'net')::numeric) > 0.02 then
      raise exception 'Snapshot member amounts do not match the server calculation. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;

    -- (c) The archived settlements must actually move each member's net:
    -- outflow - inflow ~= -net for every member.
    select coalesce(sum((s.value->>'amount')::numeric) filter (where s.value->>'fromId' = computed_person->>'id'), 0)
         - coalesce(sum((s.value->>'amount')::numeric) filter (where s.value->>'toId' = computed_person->>'id'), 0)
      into snapshot_flow
      from jsonb_array_elements(coalesce(period_snapshot->'settlements', '[]'::jsonb)) as s(value);

    if abs(snapshot_flow + (computed_person->>'net')::numeric) > 0.05 then
      raise exception 'Snapshot settlements do not match the member balances. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;
  end loop;

  -- Snapshot-only members (left the ledger between fetch and close) must carry
  -- no money, otherwise the archive would hide a real balance.
  for snapshot_person in
    select value from jsonb_array_elements(coalesce(period_snapshot->'people', '[]'::jsonb))
  loop
    if not exists (
      select 1 from jsonb_array_elements(computed->'people') as c(value)
      where c.value->>'id' = snapshot_person->>'id'
    ) and abs(coalesce((snapshot_person->>'net')::numeric, 0)) > 0.02 then
      raise exception 'Snapshot includes a member the server no longer recognizes. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;
  end loop;
  -- ── End integrity gate ────────────────────────────────────────────────────

  -- ── FIX 2 (GV-253 / GVM-278): require requests before close ────────────────
  -- rule_require_requests_before_close (migration 098) shipped stored-only — this
  -- is its first database enforcement. When the workspace flag is NOT an explicit
  -- false, every settlement pair that moves money must already have a request row
  -- for this period in a requested-or-later state (status not 'open'/'cancelled').
  -- The period_snapshot settlements are safe to read here: integrity gate (c) just
  -- proved they reconcile each member's server-computed net, so they ARE the real
  -- outstanding pairs. A settlement_requests row is keyed by period + payer
  -- (from_member_id) + recipient (to_member_id), matching the snapshot fromId/toId.
  select l.rule_require_requests_before_close
    into v_rule_require_requests
    from public.ledgers l
    where l.id = target_ledger_id;

  if v_rule_require_requests is not false then
    for v_settlement in
      select value from jsonb_array_elements(coalesce(period_snapshot->'settlements', '[]'::jsonb))
    loop
      if coalesce((v_settlement->>'amount')::numeric, 0) > 0
         and not exists (
           select 1
           from public.settlement_requests sr
           where sr.period_id = target_period_id
             and sr.from_member_id = (v_settlement->>'fromId')::uuid
             and sr.to_member_id = (v_settlement->>'toId')::uuid
             and sr.status not in ('open', 'cancelled')
             and sr.amount = round((v_settlement->>'amount')::numeric, 2)
         ) then
        v_missing_settlements := v_missing_settlements + 1;
      end if;
    end loop;

    if v_missing_settlements > 0 then
      raise exception
        'All settlements must be requested at their current amounts before this period can be closed. Request or update the outstanding payments and try again.'
        using errcode = '42501';
    end if;
  end if;
  -- ── End require-requests-before-close ──────────────────────────────────────

  if snapshot_fingerprint is not null then
    select sp.id into duplicate_period_id
    from public.settlement_periods sp
    where sp.ledger_id = target_ledger_id
      and sp.status = 'closed'
      and sp.snapshot_json->>'entryFingerprint' = snapshot_fingerprint
    limit 1;

    if duplicate_period_id is not null then
      raise exception 'This settlement period snapshot has already been closed' using errcode = '23505';
    end if;
  end if;

  begin
    requested_closed_at := coalesce((period_snapshot->>'closedAt')::timestamptz, now());
  exception when others then
    requested_closed_at := now();
  end;

  -- GV-277: bind this period's remaining legacy null-period repairs to it BEFORE
  -- the period flips to closed, so enforce_repair_period_lock (which freezes a
  -- repair once its period is closed) still permits this write. A stamped repair
  -- already carries period_id from insert_repair; only pre-114 rows are updated
  -- here, matched by the same created_at window the settlement/fingerprint use.
  update public.vehicle_repairs vr
  set period_id = target_period_id
  from public.settlement_periods sp
  where sp.id = target_period_id
    and sp.ledger_id = target_ledger_id
    and vr.ledger_id = target_ledger_id
    and vr.period_id is null
    and vr.deleted_at is null
    and vr.created_at >= sp.opened_at
    and vr.created_at < requested_closed_at;

  update public.settlement_periods sp
  set status = 'closed',
      label = coalesce(nullif(period_snapshot->>'label', ''), sp.label, 'Closed period'),
      closed_at = requested_closed_at,
      closed_by_member_id = actor_member_id,
      snapshot_json = period_snapshot,
      updated_at = now()
  where sp.id = target_period_id
    and sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  returning sp.id into closed_period_id;

  if closed_period_id is null then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '40001';
  end if;

  -- FIX 3 (GV-253): label the freshly opened period in Danish to match the app's
  -- own period labels (client formats da-DK month+year; demo data uses 'Juni
  -- 2026'). to_char(..., 'Month') only speaks English, so index a Danish month
  -- array by the current month and capitalize, e.g. 'Juli 2026'. Deterministic and
  -- server-clock based; the client overwrites this with its own snapshot label when
  -- it later closes, so it only shows while this is the current period.
  insert into public.settlement_periods (ledger_id, status, label, opened_at)
  values (
    target_ledger_id,
    'open',
    (array['Januar','Februar','Marts','April','Maj','Juni','Juli','August','September','Oktober','November','December'])[extract(month from now())::int]
      || ' ' || to_char(now(), 'YYYY'),
    now()
  )
  returning id into new_open_period_id;

  -- Activity feed + realtime nudge (GVM-247): closing a period writes a
  -- ledger_events row so every other member's client (subscribed to
  -- ledger_events) refetches immediately — otherwise the close only reaches them
  -- on a manual refresh. metadata carries both period ids for the feed/routing.
  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id, 'period_closed', 'Periode lukket', 'En ny periode er klar.',
    actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
    jsonb_build_object('closed_period_id', closed_period_id, 'open_period_id', new_open_period_id)
  );

  return jsonb_build_object(
    'closed_period_id', closed_period_id,
    'open_period_id', new_open_period_id,
    'closed_by_member_id', actor_member_id,
    'closed_at', requested_closed_at,
    'entry_fingerprint', snapshot_fingerprint
  );
end;
$$;

revoke execute on function public.close_settlement_period(text, uuid, jsonb) from public;
grant execute on function public.close_settlement_period(text, uuid, jsonb) to authenticated;

-- ── B.1: set_ledger_member_active_admin — suspend the payer's recurring templates ──
-- Re-declared off migration 012 (its newest prior definition). The admin gate,
-- self-deactivation guard, member update and last-admin guard are 012 verbatim. The
-- GV-277 addition: when the member is being DEACTIVATED, suspend (is_active = false)
-- every recurring-expense template they PAY for and write a 'recurring_suspended'
-- ledger_events row (Danish, naming the templates) so admins get an action item to
-- reassign the payer or delete the template. This runs after the last-admin guard,
-- so a rejected deactivation rolls the suspension back with the rest of the txn.
create or replace function public.set_ledger_member_active_admin(
  target_ledger_id text default 'main-car',
  target_member_id uuid default null,
  member_is_active boolean default true
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  existing_member public.ledger_members%rowtype;
  active_admin_count integer := 0;
  suspended_count integer := 0;
  suspended_names text;
begin
  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can activate or deactivate members' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not identify the current ledger admin' using errcode = '42501';
  end if;

  if target_member_id is null then
    raise exception 'Member id is required' using errcode = '23502';
  end if;

  perform pg_advisory_xact_lock(hashtext(target_ledger_id || ':member-admin'));

  select * into existing_member
  from public.ledger_members
  where id = target_member_id and ledger_id = target_ledger_id
  for update;

  if existing_member.id is null then
    raise exception 'Member does not belong to this ledger' using errcode = '23503';
  end if;

  if existing_member.id = actor_member_id and member_is_active is false then
    raise exception 'Admins cannot deactivate themselves' using errcode = '42501';
  end if;

  update public.ledger_members
  set is_active = coalesce(member_is_active, true), updated_at = now()
  where id = target_member_id and ledger_id = target_ledger_id;

  select count(*) into active_admin_count
  from public.ledger_members
  where ledger_id = target_ledger_id and is_active = true and role = 'admin';

  if active_admin_count < 1 then
    raise exception 'At least one active admin is required' using errcode = '23514';
  end if;

  -- GV-277: on deactivation, suspend every recurring template the member fronts.
  -- Left active, the generators would keep charging an inactive payer (credit-only
  -- in the settlement since 112), silently distorting balances. The event gives
  -- admins an action item to reassign the payer or delete the template.
  if coalesce(member_is_active, true) is false then
    with suspended as (
      update public.recurring_expenses re
      set is_active = false, updated_at = now()
      where re.ledger_id = target_ledger_id
        and re.paid_by_member_id = target_member_id
        and re.is_active = true
        and re.deleted_at is null
      returning re.description, re.category
    )
    select count(*),
           string_agg(coalesce(nullif(btrim(s.description), ''), initcap(s.category)),
                      ', ' order by coalesce(nullif(btrim(s.description), ''), initcap(s.category)))
      into suspended_count, suspended_names
      from suspended s;

    if suspended_count > 0 then
      insert into public.ledger_events (
        ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata
      ) values (
        target_ledger_id,
        'recurring_suspended',
        'Faste udgifter sat på pause',
        coalesce(existing_member.name, 'Et medlem')
          || ' blev deaktiveret, så deres faste udgifter blev sat på pause: '
          || suspended_names
          || '. Vælg en ny betaler eller slet dem.',
        actor_member_id,
        nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
        target_member_id,
        jsonb_build_object('deactivated_member_id', target_member_id, 'suspended_count', suspended_count)
      );
    end if;
  end if;

  return target_member_id;
end;
$$;

revoke all on function public.set_ledger_member_active_admin(text, uuid, boolean) from public;
revoke all on function public.set_ledger_member_active_admin(text, uuid, boolean) from anon;
grant execute on function public.set_ledger_member_active_admin(text, uuid, boolean) to authenticated;

-- ── B.2: generate_due_recurring_expenses — skip inactive-payer templates ────────
-- Re-declared off migration 112 (its newest prior definition). Body is 112 verbatim
-- plus one GV-277 guard on the template scan: skip a template whose payer is a known
-- inactive member (defense in depth — set_ledger_member_active_admin already
-- suspends them, but a template edited to an inactive payer is caught here too).
-- member_is_active_in_ledger returns true for a null payer, so legacy null-payer
-- templates are unaffected.
create or replace function public.generate_due_recurring_expenses(
  target_ledger_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  total_generated integer := 0;
  -- Bound the per-template catch-up so one stale template can't materialise an
  -- unbounded backlog in a single run; the remainder catches up on later runs
  -- (GV-274). Same value in generate_all_due_recurring_expenses (the scheduler).
  max_catchup_occurrences constant integer := 24;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can generate recurring expenses' using errcode = '42501';
  end if;

  -- Materialise into the ledger's open period. If none is open (should not happen
  -- after bootstrap, but a period close briefly precedes the next open), do
  -- nothing this run; the next call catches up. FOR SHARE serializes against a
  -- concurrent close (which exclusively locks the period row).
  select sp.id into open_period_id
  from public.settlement_periods sp
  where sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  order by sp.opened_at desc
  limit 1
  for share of sp;

  if open_period_id is null then
    return jsonb_build_object('generated', 0, 'reason', 'no_open_period');
  end if;

  for tmpl in
    select *
    from public.recurring_expenses r
    where r.ledger_id = target_ledger_id
      and r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
    order by r.next_due_date
    for update skip locked
  loop
    due_date := tmpl.next_due_date;
    template_count := 0;
    occurrences := 0;

    while due_date <= current_date and occurrences < max_catchup_occurrences loop
      insert into public.workspace_expenses (
        ledger_id, period_id, category, description, amount_dkk, expense_date,
        split_rule, split_config, paid_by_member_id, created_by_member_id,
        recurring_expense_id, occurrence_date
      ) values (
        target_ledger_id,
        open_period_id,
        tmpl.category,
        tmpl.description,
        tmpl.amount_dkk,
        due_date,
        tmpl.split_rule,
        tmpl.split_config,
        tmpl.paid_by_member_id,
        tmpl.created_by_member_id,
        tmpl.id,
        due_date
      )
      on conflict (recurring_expense_id, occurrence_date)
        where recurring_expense_id is not null do nothing
      returning id into inserted_id;

      if inserted_id is not null then
        template_count := template_count + 1;
      end if;
      inserted_id := null;
      occurrences := occurrences + 1;

      due_date := (case tmpl.cadence
        when 'monthly' then due_date + interval '1 month'
        when 'quarterly' then due_date + interval '3 months'
        when 'semiannual' then due_date + interval '6 months'
        when 'yearly' then due_date + interval '1 year'
        else due_date + interval '1 month'
      end)::date;
    end loop;

    update public.recurring_expenses
      set next_due_date = due_date, last_generated_at = now(), updated_at = now()
    where id = tmpl.id;

    if template_count > 0 then
      insert into public.ledger_events (
        ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
      ) values (
        target_ledger_id,
        'expense_recurring_added',
        'Fast udgift tilføjet',
        coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
          || ' blev automatisk tilføjet og delt.',
        null,
        null,
        jsonb_build_object(
          'category', tmpl.category,
          'recurring_expense_id', tmpl.id,
          'count', template_count
        )
      );
      total_generated := total_generated + template_count;
    end if;
  end loop;

  return jsonb_build_object('generated', total_generated);
end;
$$;

revoke all on function public.generate_due_recurring_expenses(text) from public;
revoke all on function public.generate_due_recurring_expenses(text) from anon;
grant execute on function public.generate_due_recurring_expenses(text) to authenticated;

-- ── B.3: generate_all_due_recurring_expenses — skip inactive-payer templates ────
-- Re-declared off migration 112 (its newest prior definition). Body is 112 verbatim
-- plus the same GV-277 payer-activity guard on BOTH the candidate-ledger scan (so a
-- ledger whose only due template has an inactive payer never occupies a batch slot)
-- and the inner template scan. Service-role only (grants restated).
create or replace function public.generate_all_due_recurring_expenses(
  batch_limit integer default 200
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  due_ledger record;
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  ledger_generated integer;
  total_generated integer := 0;
  ledgers_touched integer := 0;
  ledgers_scanned integer := 0;
  -- Same per-template catch-up bound as generate_due_recurring_expenses (GV-274).
  max_catchup_occurrences constant integer := 24;
begin
  for due_ledger in
    -- Only ledgers with a due active template (with an active payer, GV-277) AND an
    -- open period to receive it, oldest debt first, so no-open-period ledgers never
    -- occupy a batch slot and the most overdue ledger is caught up first under
    -- batch_limit (GV-274).
    select r.ledger_id
    from public.recurring_expenses r
    where r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
      and exists (
        select 1
        from public.settlement_periods sp
        where sp.ledger_id = r.ledger_id
          and sp.status = 'open'
          and sp.closed_at is null
      )
    group by r.ledger_id
    order by min(r.next_due_date) asc, r.ledger_id
    limit greatest(coalesce(batch_limit, 200), 0)
  loop
    ledgers_scanned := ledgers_scanned + 1;

    -- Materialise into the ledger's open period. If none is open (a period close
    -- briefly precedes the next open), skip this ledger this run; the next tick catches
    -- up. FOR SHARE serializes against a concurrent close (which exclusively locks the
    -- period row).
    select sp.id into open_period_id
    from public.settlement_periods sp
    where sp.ledger_id = due_ledger.ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    order by sp.opened_at desc
    limit 1
    for share of sp;

    if open_period_id is null then
      open_period_id := null;
      continue;
    end if;

    ledger_generated := 0;

    for tmpl in
      select *
      from public.recurring_expenses r
      where r.ledger_id = due_ledger.ledger_id
        and r.is_active
        and r.deleted_at is null
        and r.next_due_date <= current_date
        and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
      order by r.next_due_date
      for update skip locked
    loop
      due_date := tmpl.next_due_date;
      template_count := 0;
      occurrences := 0;

      while due_date <= current_date and occurrences < max_catchup_occurrences loop
        insert into public.workspace_expenses (
          ledger_id, period_id, category, description, amount_dkk, expense_date,
          split_rule, split_config, paid_by_member_id, created_by_member_id,
          recurring_expense_id, occurrence_date
        ) values (
          due_ledger.ledger_id,
          open_period_id,
          tmpl.category,
          tmpl.description,
          tmpl.amount_dkk,
          due_date,
          tmpl.split_rule,
          tmpl.split_config,
          tmpl.paid_by_member_id,
          tmpl.created_by_member_id,
          tmpl.id,
          due_date
        )
        on conflict (recurring_expense_id, occurrence_date)
          where recurring_expense_id is not null do nothing
        returning id into inserted_id;

        if inserted_id is not null then
          template_count := template_count + 1;
        end if;
        inserted_id := null;
        occurrences := occurrences + 1;

        due_date := (case tmpl.cadence
          when 'monthly' then due_date + interval '1 month'
          when 'quarterly' then due_date + interval '3 months'
          when 'semiannual' then due_date + interval '6 months'
          when 'yearly' then due_date + interval '1 year'
          else due_date + interval '1 month'
        end)::date;
      end loop;

      update public.recurring_expenses
        set next_due_date = due_date, last_generated_at = now(), updated_at = now()
      where id = tmpl.id;

      if template_count > 0 then
        insert into public.ledger_events (
          ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
        ) values (
          due_ledger.ledger_id,
          'expense_recurring_added',
          'Fast udgift tilføjet',
          coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
            || ' blev automatisk tilføjet og delt.',
          null,
          null,
          jsonb_build_object(
            'category', tmpl.category,
            'recurring_expense_id', tmpl.id,
            'count', template_count
          )
        );
        ledger_generated := ledger_generated + template_count;
      end if;
    end loop;

    if ledger_generated > 0 then
      ledgers_touched := ledgers_touched + 1;
      total_generated := total_generated + ledger_generated;
    end if;

    open_period_id := null;
  end loop;

  return jsonb_build_object(
    'generated', total_generated,
    'ledgers_touched', ledgers_touched,
    'ledgers_scanned', ledgers_scanned
  );
end;
$$;

revoke execute on function public.generate_all_due_recurring_expenses(integer) from public;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from anon;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from authenticated;
grant execute on function public.generate_all_due_recurring_expenses(integer) to service_role;

-- ── Register migration ──────────────────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('114_repair_period_binding_and_deactivation',
        'Repair↔period binding + payer-deactivation recurring suspension (GV-277). A) vehicle_repairs.period_id added (nullable FK, on delete set null). insert_repair re-declared off 108: takes the blocking ledger advisory lock close_settlement_period uses (pg_advisory_xact_lock(hashtext(ledger_id))) so a repair insert queues behind an in-flight close, then stamps the open period id. calculate_period_settlement (off 112) and calculate_period_entry_fingerprint (off 112) scope repairs by period_id, falling back to the 112 created_at window for legacy null-period rows; the fingerprint''s repair component becomes id+oere PAIRS so a repair-cost edit busts a prepared close (the amount guard misses it — repairs move neither totalKm nor totalPaid), key still omitted when empty and mirrored byte-identically by the mobile client. close_settlement_period (off 104) stamps period_id on the closing period''s remaining legacy null-period repairs before flipping it to closed (so enforce_repair_period_lock permits the write). B) set_ledger_member_active_admin (off 012): on deactivation, suspends every recurring template the member pays for and writes a recurring_suspended ledger_events row (Danish, naming the templates). Both recurring generators (off 112) additionally skip templates whose payer is a known inactive member (defense in depth; member_is_active_in_ledger returns true for a null payer).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();


-- ── Migration 115: payment evidence notes on the paid_pending/dispute lifecycle (GV-279, GVM-331) ──
alter table public.settlement_requests
  add column if not exists paid_note text,
  add column if not exists dispute_note text;

alter table public.settlement_requests
  drop constraint if exists settlement_requests_paid_note_len,
  add constraint settlement_requests_paid_note_len
    check (paid_note is null or char_length(paid_note) <= 280);

alter table public.settlement_requests
  drop constraint if exists settlement_requests_dispute_note_len,
  add constraint settlement_requests_dispute_note_len
    check (dispute_note is null or char_length(dispute_note) <= 280);

drop function if exists public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[]);
create or replace function public.upsert_settlement_request_status(
  target_ledger_id text,
  target_open_period_id uuid,
  payer_member_id uuid,
  recipient_member_id uuid,
  amount_value numeric,
  currency_value text,
  next_status text,
  current_pair_keys text[] default array[]::text[],
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  saved_request_id uuid;
  prev_status_value text := null;
  prev_amount_value numeric := null;
  prev_currency_value text := null;
  prev_paid_note text := null;
  prev_dispute_note text := null;
  final_paid_note text := null;
  final_dispute_note text := null;
  event_note_value text := null;
  requested_at_value timestamptz := null;
  requested_by_value uuid := null;
  paid_at_value timestamptz := null;
  cancelled_count integer := 0;
  normalized_status text := coalesce(nullif(next_status, ''), 'open');
  normalized_note text := nullif(btrim(p_note), '');
  event_type_value text;
  event_title_value text;
  period_is_open boolean;
  computed_settlement jsonb;
  valid_pair_keys text[] := array[]::text[];
  debtor_ids uuid[];
  debtor_amts numeric[];
  creditor_ids uuid[];
  creditor_amts numeric[];
  di integer := 1;
  ci integer := 1;
  pair_amount numeric;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_open_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can save settlement requests' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- GV-244: a settlement request may only be created or transitioned by one of
  -- its two parties or a ledger admin. Without this any signed-in member could
  -- drive a request between two OTHER members (incl. marking it paid) through
  -- this SECURITY DEFINER RPC, bypassing the party-or-admin table RLS.
  if actor_member_id not in (payer_member_id, recipient_member_id)
    and not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only the payer, recipient, or a ledger admin can save this settlement request' using errcode = '42501';
  end if;

  -- Resolve the target period. Normally OPEN (request + pay on the live period).
  -- For a debt carried past a close, mobile acts on the request in its own CLOSED
  -- period (GVM-243): mark paid / remind / reopen are allowed there, but only
  -- against an existing request (guarded below). A missing/foreign period is
  -- rejected outright.
  select (sp.status = 'open' and sp.closed_at is null)
    into period_is_open
  from public.settlement_periods sp
  where sp.id = target_open_period_id
    and sp.ledger_id = target_ledger_id;

  if period_is_open is null then
    raise exception 'Settlement period was not found or does not belong to this ledger' using errcode = '22023';
  end if;

  if payer_member_id is null or recipient_member_id is null then
    raise exception 'Settlement request must include both payer and recipient members' using errcode = '23514';
  end if;

  if payer_member_id = recipient_member_id then
    raise exception 'Settlement request payer and recipient must be different members' using errcode = '23514';
  end if;

  if not public.member_belongs_to_ledger(payer_member_id, target_ledger_id)
    or not public.member_belongs_to_ledger(recipient_member_id, target_ledger_id) then
    raise exception 'Settlement request members must belong to the same ledger' using errcode = '23514';
  end if;

  if amount_value is null or amount_value < 0 then
    raise exception 'Settlement request amount must be zero or greater' using errcode = '23514';
  end if;

  if normalized_status not in ('open', 'requested', 'paid', 'paid_pending', 'cancelled') then
    raise exception 'Invalid settlement request status' using errcode = '23514';
  end if;

  -- A closed period can gain no NEW requests: only an existing (non-cancelled)
  -- request for the pair may transition. This blanket-guards paid / requested /
  -- open on a closed period; the insert branch + stale sweep below stay
  -- open-period-only.
  if not period_is_open then
    if not exists (
      select 1 from public.settlement_requests sr
      where sr.period_id = target_open_period_id
        and sr.from_member_id = payer_member_id
        and sr.to_member_id = recipient_member_id
        and sr.status <> 'cancelled'
    ) then
      raise exception 'No active settlement request for this pair in the closed period' using errcode = '22023';
    end if;
  end if;

  -- Bound the requested amount (GVM-112): no pair settlement can exceed the
  -- period's total fuel spend. Deliberately an upper bound, not equality —
  -- monthly/running request shapes (GVM-76) vary by design, and a false
  -- rejection would block a legitimate payment request. Open-period only: a
  -- closed period's fuel total is frozen and the amount already exists on the row.
  if normalized_status = 'requested' and period_is_open then
    if amount_value is null or amount_value <= 0 then
      raise exception 'Requested amount must be greater than zero' using errcode = '23514';
    end if;
    if amount_value > (
      select coalesce(sum(fp.amount), 0) + 1.0
      from public.fuel_payments fp
      where fp.ledger_id = target_ledger_id
        and fp.period_id = target_open_period_id
        and fp.deleted_at is null
    ) then
      raise exception 'Requested amount is larger than this period''s total fuel spend. Refresh the app and try again.' using errcode = '23514';
    end if;
  end if;

  -- Require an existing, non-cancelled request before claiming or confirming a
  -- payment (GVM-241, extended to paid_pending in GVM-213). Without this the
  -- pair upsert's on-conflict misses for a stale/foreign-period request and
  -- INSERTs a fresh row directly at a settled-ish status, which trips the 003
  -- trigger guard with the cryptic 'Request the payment before marking it paid'.
  -- Raise a clean, mappable error instead.
  if normalized_status in ('paid', 'paid_pending') then
    if not exists (
      select 1 from public.settlement_requests sr
      where sr.period_id = target_open_period_id
        and sr.from_member_id = payer_member_id
        and sr.to_member_id = recipient_member_id
        and sr.status <> 'cancelled'
    ) then
      raise exception 'No active payment request to mark as paid — refresh and try again' using errcode = '23514';
    end if;
  end if;

  if normalized_status = 'requested' then
    requested_at_value := now();
    requested_by_value := recipient_member_id;
  elsif normalized_status = 'paid' then
    paid_at_value := now();
  end if;

  perform pg_advisory_xact_lock(hashtext(target_ledger_id || ':settlement:' || target_open_period_id::text));

  -- Transition the pair's request via an explicit lookup + UPDATE, NOT
  -- INSERT ... ON CONFLICT. The 003 integrity trigger is BEFORE INSERT OR UPDATE,
  -- and a BEFORE INSERT trigger fires on an upsert's proposed row *before* the
  -- ON CONFLICT resolves to DO UPDATE — so an upsert to a settled status trips
  -- the trigger's INSERT guard even when a matching request exists (GVM-241).
  -- An explicit UPDATE fires BEFORE UPDATE, where the guard validates the
  -- transition as legal. Genuinely new rows still INSERT (open period only — a
  -- closed period was guaranteed an existing request above). prev_status drives
  -- the dispute event below (a paid_pending row sent back to 'requested').
  select sr.id, sr.status, sr.amount, sr.currency, sr.paid_note, sr.dispute_note
    into saved_request_id, prev_status_value, prev_amount_value, prev_currency_value, prev_paid_note, prev_dispute_note
  from public.settlement_requests sr
  where sr.period_id = target_open_period_id
    and sr.from_member_id = payer_member_id
    and sr.to_member_id = recipient_member_id
    and sr.status <> 'cancelled'
  for update;

  -- GV-259: amount + currency are IMMUTABLE once a request has left 'open'. The
  -- single permitted adjustment is the creditor (recipient) or a ledger admin
  -- re-requesting a still-live 'requested' row when balances shift (the mobile
  -- re-request flow). Every other transition — anything touching
  -- paid_pending/paid/cancelled, or the payer acting — must carry the stored
  -- amount + currency unchanged, so a claimed/settled figure can never be
  -- rewritten under a status change. Creation ('open' or no row) sets the amount
  -- freely and is skipped here.
  if saved_request_id is not null and prev_status_value <> 'open' then
    if normalized_status = 'requested'
       and (actor_member_id = recipient_member_id
            or public.is_ledger_admin(target_ledger_id)) then
      null; -- creditor/admin may re-request a live request at a new amount
    elsif amount_value = prev_amount_value
          and coalesce(nullif(currency_value, ''), 'DKK') = prev_currency_value then
      null; -- amount + currency preserved
    else
      raise exception 'Settlement request amount is locked during status transitions' using errcode = '23514';
    end if;
  end if;

  -- GV-279: payment evidence notes. Only two transitions persist a note, and each
  -- is IMMUTABLE once set (a repeat call keeps the existing note via coalesce):
  --   * the DEBTOR (payer) claiming payment → paid_pending writes paid_note;
  --   * the CREDITOR (recipient) disputing a claim (paid_pending → requested)
  --     writes dispute_note.
  -- Every other transition, and any other actor, leaves both notes untouched.
  final_paid_note := prev_paid_note;
  final_dispute_note := prev_dispute_note;
  if normalized_status = 'paid_pending' and actor_member_id = payer_member_id then
    final_paid_note := coalesce(prev_paid_note, normalized_note);
  elsif normalized_status = 'requested'
        and prev_status_value = 'paid_pending'
        and actor_member_id = recipient_member_id then
    final_dispute_note := coalesce(prev_dispute_note, normalized_note);
  end if;
  event_note_value := case
    when normalized_status = 'paid_pending' and actor_member_id = payer_member_id then final_paid_note
    when normalized_status = 'requested'
         and prev_status_value = 'paid_pending'
         and actor_member_id = recipient_member_id then final_dispute_note
    else null
  end;

  if saved_request_id is not null then
    update public.settlement_requests
       set amount = amount_value,
           currency = coalesce(nullif(currency_value, ''), 'DKK'),
           status = normalized_status,
           requested_at = requested_at_value,
           requested_by_member_id = requested_by_value,
           paid_at = paid_at_value,
           paid_note = final_paid_note,
           dispute_note = final_dispute_note,
           updated_at = now()
     where id = saved_request_id;
  elsif period_is_open then
    insert into public.settlement_requests (
      ledger_id,
      period_id,
      from_member_id,
      to_member_id,
      amount,
      currency,
      status,
      requested_at,
      requested_by_member_id,
      paid_at,
      paid_note,
      dispute_note,
      updated_at
    ) values (
      target_ledger_id,
      target_open_period_id,
      payer_member_id,
      recipient_member_id,
      amount_value,
      coalesce(nullif(currency_value, ''), 'DKK'),
      normalized_status,
      requested_at_value,
      requested_by_value,
      paid_at_value,
      final_paid_note,
      final_dispute_note,
      now()
    )
    returning id into saved_request_id;
  else
    raise exception 'No active settlement request for this pair in the closed period' using errcode = '22023';
  end if;

  -- GV-259: cancel stale requests whose pair is no longer part of the live
  -- settlement. The set of valid pairs is computed SERVER-SIDE (current_pair_keys
  -- is ignored): calculate_period_settlement returns each member's net, and the
  -- valid (debtor -> creditor) pairs are derived from those nets with the same
  -- greedy min-cash-flow the client uses (settlement-calc.ts / buildSettlements).
  -- Open-period only, as before: a closed period's settlements are frozen. Only
  -- 'open'/'requested' rows are swept — a paid_pending/paid row is money already
  -- claimed or moved (history, not staleness) and is never cancelled here.
  if period_is_open then
    computed_settlement := public.calculate_period_settlement(target_ledger_id, target_open_period_id);

    -- Debtors carry net < 0 (owe money), creditors net > 0 (are owed). Each side
    -- is ordered by magnitude descending, matching the client's debtor/creditor
    -- sort; ties break on id for a deterministic server result. Amounts round to
    -- 2 dp (nets are already 2 dp; round is a defensive no-op).
    select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::uuid[]),
           coalesce(array_agg(round(-((p.value->>'net')::numeric), 2) order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::numeric[])
      into debtor_ids, debtor_amts
      from jsonb_array_elements(computed_settlement->'people') as p(value)
      where (p.value->>'net')::numeric < -0.005;

    select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::uuid[]),
           coalesce(array_agg(round((p.value->>'net')::numeric, 2) order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::numeric[])
      into creditor_ids, creditor_amts
      from jsonb_array_elements(computed_settlement->'people') as p(value)
      where (p.value->>'net')::numeric > 0.005;

    -- Greedy min-cash-flow pairing (mirrors buildSettlements): match the largest
    -- debtor against the largest creditor, emit a 'fromId->toId' key when the
    -- matched amount rounds > 0, then advance whichever side is exhausted. Every
    -- matched amount is <= 0.005 => index advances, so the loop always terminates.
    while di <= coalesce(array_length(debtor_ids, 1), 0)
          and ci <= coalesce(array_length(creditor_ids, 1), 0) loop
      pair_amount := round(least(debtor_amts[di], creditor_amts[ci]), 2);
      if pair_amount > 0 then
        valid_pair_keys := valid_pair_keys
          || (debtor_ids[di]::text || '->' || creditor_ids[ci]::text);
      end if;
      debtor_amts[di] := round(debtor_amts[di] - pair_amount, 2);
      creditor_amts[ci] := round(creditor_amts[ci] - pair_amount, 2);
      if debtor_amts[di] <= 0.005 then di := di + 1; end if;
      if creditor_amts[ci] <= 0.005 then ci := ci + 1; end if;
    end loop;

    update public.settlement_requests sr
       set status = 'cancelled',
           updated_at = now(),
           requested_at = null,
           requested_by_member_id = null,
           paid_at = null
     where sr.ledger_id = target_ledger_id
       and sr.period_id = target_open_period_id
       and sr.status in ('open', 'requested')
       and not ((sr.from_member_id::text || '->' || sr.to_member_id::text) = any(valid_pair_keys));
    get diagnostics cancelled_count = row_count;
  end if;

  -- Activity feed + realtime nudge (GVM-247): every status change writes a
  -- ledger_events row so the other member's client (subscribed to ledger_events)
  -- refetches immediately, and the change lands in the activity feed. The
  -- two-step confirmation (GVM-213) adds payment_claimed (debtor marked paid,
  -- awaiting confirmation) and payment_disputed (recipient sent a paid_pending
  -- debt back to 'requested'); payment_paid now means confirmed/received. GV-279
  -- carries the evidence note (paid_note on a claim, dispute_note on a dispute)
  -- in metadata 'note' so the feed and push can surface it.
  event_type_value := case
    when normalized_status = 'requested' and prev_status_value = 'paid_pending' then 'payment_disputed'
    when normalized_status = 'requested' then 'payment_requested'
    when normalized_status = 'paid_pending' then 'payment_claimed'
    when normalized_status = 'paid' then 'payment_paid'
    else 'settlement_' || normalized_status
  end;
  event_title_value := case
    when normalized_status = 'requested' and prev_status_value = 'paid_pending' then 'Betaling afvist'
    when normalized_status = 'requested' then 'Betaling anmodet'
    when normalized_status = 'paid_pending' then 'Afventer bekræftelse'
    when normalized_status = 'paid' then 'Betaling bekræftet'
    when normalized_status = 'cancelled' then 'Betaling annulleret'
    else 'Betaling genåbnet'
  end;

  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id, event_type_value, event_title_value, '',
    actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
    jsonb_build_object(
      'settlement_request_id', saved_request_id,
      'from_member_id', payer_member_id,
      'to_member_id', recipient_member_id,
      'amount', amount_value,
      'note', event_note_value
    )
  );

  return jsonb_build_object(
    'settlement_request_id', saved_request_id,
    'ledger_id', target_ledger_id,
    'period_id', target_open_period_id,
    'status', normalized_status,
    'cancelled_stale_count', cancelled_count
  );
end;
$$;

revoke execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[], text) from public;
grant execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[], text) to authenticated;

-- ── Register migration ──────────────────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('115_payment_evidence_notes',
        'Payment evidence notes (GV-279, GVM-331). settlement_requests gains paid_note + dispute_note (text, ≤ 280 chars, CHECK-guarded). upsert_settlement_request_status re-declared off 104 (old 8-arg dropped, replaced by a 9-arg function) with a trailing p_note text default null: the debtor''s paid_pending claim writes paid_note, the creditor''s dispute (paid_pending -> requested) writes dispute_note, every other transition/actor ignores it; both notes are immutable once set (coalesce keep-existing) and echoed into ledger_events metadata ''note''. Status transitions still UPDATE the existing row (BEFORE INSERT trigger rejects non-open inserts).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── generate_due_recurring_expenses — skip when the open period is entry-locked ─
-- Re-declared off migration 114 (its newest prior definition). Body is 114 verbatim
-- plus one GV-281 guard: bail with a zero-summary when the open period is locked,
-- instead of letting the entry-lock trigger raise 42501 into the client's catch-up.
create or replace function public.generate_due_recurring_expenses(
  target_ledger_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  total_generated integer := 0;
  -- Bound the per-template catch-up so one stale template can't materialise an
  -- unbounded backlog in a single run; the remainder catches up on later runs
  -- (GV-274). Same value in generate_all_due_recurring_expenses (the scheduler).
  max_catchup_occurrences constant integer := 24;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can generate recurring expenses' using errcode = '42501';
  end if;

  -- Materialise into the ledger's open period. If none is open (should not happen
  -- after bootstrap, but a period close briefly precedes the next open), do
  -- nothing this run; the next call catches up. FOR SHARE serializes against a
  -- concurrent close (which exclusively locks the period row).
  select sp.id into open_period_id
  from public.settlement_periods sp
  where sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  order by sp.opened_at desc
  limit 1
  for share of sp;

  if open_period_id is null then
    return jsonb_build_object('generated', 0, 'reason', 'no_open_period');
  end if;

  -- GV-281: if the open period is entry-locked (an active settlement request has
  -- been requested/paid), skip generation this run rather than raising 42501 from
  -- the enforce_settlement_entry_lock trigger — which used to crash the client's
  -- on-load catch-up. The deferred occurrence is caught up automatically once the
  -- payment completes/cancels or the period closes and a new one opens.
  if public.settlement_entry_is_locked(target_ledger_id, open_period_id) then
    return jsonb_build_object('generated', 0, 'reason', 'locked');
  end if;

  for tmpl in
    select *
    from public.recurring_expenses r
    where r.ledger_id = target_ledger_id
      and r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
    order by r.next_due_date
    for update skip locked
  loop
    due_date := tmpl.next_due_date;
    template_count := 0;
    occurrences := 0;

    while due_date <= current_date and occurrences < max_catchup_occurrences loop
      insert into public.workspace_expenses (
        ledger_id, period_id, category, description, amount_dkk, expense_date,
        split_rule, split_config, paid_by_member_id, created_by_member_id,
        recurring_expense_id, occurrence_date
      ) values (
        target_ledger_id,
        open_period_id,
        tmpl.category,
        tmpl.description,
        tmpl.amount_dkk,
        due_date,
        tmpl.split_rule,
        tmpl.split_config,
        tmpl.paid_by_member_id,
        tmpl.created_by_member_id,
        tmpl.id,
        due_date
      )
      on conflict (recurring_expense_id, occurrence_date)
        where recurring_expense_id is not null do nothing
      returning id into inserted_id;

      if inserted_id is not null then
        template_count := template_count + 1;
      end if;
      inserted_id := null;
      occurrences := occurrences + 1;

      due_date := (case tmpl.cadence
        when 'monthly' then due_date + interval '1 month'
        when 'quarterly' then due_date + interval '3 months'
        when 'semiannual' then due_date + interval '6 months'
        when 'yearly' then due_date + interval '1 year'
        else due_date + interval '1 month'
      end)::date;
    end loop;

    update public.recurring_expenses
      set next_due_date = due_date, last_generated_at = now(), updated_at = now()
    where id = tmpl.id;

    if template_count > 0 then
      insert into public.ledger_events (
        ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
      ) values (
        target_ledger_id,
        'expense_recurring_added',
        'Fast udgift tilføjet',
        coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
          || ' blev automatisk tilføjet og delt.',
        null,
        null,
        jsonb_build_object(
          'category', tmpl.category,
          'recurring_expense_id', tmpl.id,
          'count', template_count
        )
      );
      total_generated := total_generated + template_count;
    end if;
  end loop;

  return jsonb_build_object('generated', total_generated);
end;
$$;

revoke all on function public.generate_due_recurring_expenses(text) from public;
revoke all on function public.generate_due_recurring_expenses(text) from anon;
grant execute on function public.generate_due_recurring_expenses(text) to authenticated;

-- ── generate_all_due_recurring_expenses — per-ledger lock skip + failure isolation ─
-- Re-declared off migration 114 (its newest prior definition). Body is 114 verbatim
-- plus the GV-281 fix: each ledger runs in its own BEGIN/EXCEPTION subtransaction, a
-- locked open period is skipped and counted, and any error rolls back only that ledger.
-- Service-role only (grants restated).
create or replace function public.generate_all_due_recurring_expenses(
  batch_limit integer default 200
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  due_ledger record;
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  ledger_generated integer;
  total_generated integer := 0;
  ledgers_touched integer := 0;
  ledgers_scanned integer := 0;
  -- GV-281: ledgers deferred this run (open period entry-locked) or rolled back on an
  -- unexpected error; first_error_code holds the FIRST failure's SQLSTATE only.
  ledgers_skipped integer := 0;
  first_error_code text := null;
  -- Same per-template catch-up bound as generate_due_recurring_expenses (GV-274).
  max_catchup_occurrences constant integer := 24;
begin
  for due_ledger in
    -- Only ledgers with a due active template (with an active payer, GV-277) AND an
    -- open period to receive it, oldest debt first, so no-open-period ledgers never
    -- occupy a batch slot and the most overdue ledger is caught up first under
    -- batch_limit (GV-274). Locked ledgers are NOT excluded here — they are skipped
    -- and counted inside the loop (GV-281) so the sweep can report ledgers_skipped.
    select r.ledger_id
    from public.recurring_expenses r
    where r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
      and exists (
        select 1
        from public.settlement_periods sp
        where sp.ledger_id = r.ledger_id
          and sp.status = 'open'
          and sp.closed_at is null
      )
    group by r.ledger_id
    order by min(r.next_due_date) asc, r.ledger_id
    limit greatest(coalesce(batch_limit, 200), 0)
  loop
    ledgers_scanned := ledgers_scanned + 1;

    -- GV-281: isolate each ledger in its own subtransaction so one bad ledger (a lock
    -- race, an unexpected constraint) can never abort the whole sweep again. On error
    -- we roll THIS ledger back (the exception block does this automatically), count it
    -- in ledgers_skipped, remember the first SQLSTATE (code only — no row values, GDPR),
    -- and CONTINUE with the next ledger.
    begin
      -- Materialise into the ledger's open period. If none is open (a period close
      -- briefly precedes the next open), skip this ledger this run; the next tick catches
      -- up. FOR SHARE serializes against a concurrent close (which exclusively locks the
      -- period row).
      select sp.id into open_period_id
      from public.settlement_periods sp
      where sp.ledger_id = due_ledger.ledger_id
        and sp.status = 'open'
        and sp.closed_at is null
      order by sp.opened_at desc
      limit 1
      for share of sp;

      if open_period_id is null then
        open_period_id := null;
        continue;
      end if;

      -- GV-281: if the open period is entry-locked (a settlement request has been
      -- requested/paid), defer this ledger without touching it. Inserting would trip the
      -- enforce_settlement_entry_lock trigger (42501); one such ledger used to abort the
      -- ENTIRE hourly sweep. The deferred occurrence is caught up on a later run once the
      -- payment completes/cancels or the period closes.
      if public.settlement_entry_is_locked(due_ledger.ledger_id, open_period_id) then
        ledgers_skipped := ledgers_skipped + 1;
        open_period_id := null;
        continue;
      end if;

      ledger_generated := 0;

      for tmpl in
        select *
        from public.recurring_expenses r
        where r.ledger_id = due_ledger.ledger_id
          and r.is_active
          and r.deleted_at is null
          and r.next_due_date <= current_date
          and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
        order by r.next_due_date
        for update skip locked
      loop
        due_date := tmpl.next_due_date;
        template_count := 0;
        occurrences := 0;

        while due_date <= current_date and occurrences < max_catchup_occurrences loop
          insert into public.workspace_expenses (
            ledger_id, period_id, category, description, amount_dkk, expense_date,
            split_rule, split_config, paid_by_member_id, created_by_member_id,
            recurring_expense_id, occurrence_date
          ) values (
            due_ledger.ledger_id,
            open_period_id,
            tmpl.category,
            tmpl.description,
            tmpl.amount_dkk,
            due_date,
            tmpl.split_rule,
            tmpl.split_config,
            tmpl.paid_by_member_id,
            tmpl.created_by_member_id,
            tmpl.id,
            due_date
          )
          on conflict (recurring_expense_id, occurrence_date)
            where recurring_expense_id is not null do nothing
          returning id into inserted_id;

          if inserted_id is not null then
            template_count := template_count + 1;
          end if;
          inserted_id := null;
          occurrences := occurrences + 1;

          due_date := (case tmpl.cadence
            when 'monthly' then due_date + interval '1 month'
            when 'quarterly' then due_date + interval '3 months'
            when 'semiannual' then due_date + interval '6 months'
            when 'yearly' then due_date + interval '1 year'
            else due_date + interval '1 month'
          end)::date;
        end loop;

        update public.recurring_expenses
          set next_due_date = due_date, last_generated_at = now(), updated_at = now()
        where id = tmpl.id;

        if template_count > 0 then
          insert into public.ledger_events (
            ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
          ) values (
            due_ledger.ledger_id,
            'expense_recurring_added',
            'Fast udgift tilføjet',
            coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
              || ' blev automatisk tilføjet og delt.',
            null,
            null,
            jsonb_build_object(
              'category', tmpl.category,
              'recurring_expense_id', tmpl.id,
              'count', template_count
            )
          );
          ledger_generated := ledger_generated + template_count;
        end if;
      end loop;

      if ledger_generated > 0 then
        ledgers_touched := ledgers_touched + 1;
        total_generated := total_generated + ledger_generated;
      end if;

      open_period_id := null;
    exception when others then
      -- Roll this ledger back (the subtransaction does this automatically) and keep
      -- sweeping. Record the first failure's SQLSTATE only — never message text or row
      -- values (GDPR).
      ledgers_skipped := ledgers_skipped + 1;
      if first_error_code is null then
        get stacked diagnostics first_error_code = returned_sqlstate;
      end if;
      open_period_id := null;
    end;
  end loop;

  return jsonb_build_object(
    'generated', total_generated,
    'ledgers_touched', ledgers_touched,
    'ledgers_scanned', ledgers_scanned,
    'ledgers_skipped', ledgers_skipped,
    'first_error', first_error_code
  );
end;
$$;

revoke execute on function public.generate_all_due_recurring_expenses(integer) from public;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from anon;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from authenticated;
grant execute on function public.generate_all_due_recurring_expenses(integer) to service_role;

-- ── Register migration ──────────────────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('116_recurring_generation_lock_skip',
        'Recurring generation skips entry-locked periods and isolates per-ledger failures (GV-281). generate_all_due_recurring_expenses (scheduler) re-declared off 114: each ledger runs in its own BEGIN/EXCEPTION subtransaction, an entry-locked open period is deferred and counted in a new ledgers_skipped key, any unexpected error rolls back only that ledger (first SQLSTATE in first_error, code only — GDPR) and the sweep continues — one locked ledger no longer 500s the hourly /api/hooks/recurring-generate batch. generate_due_recurring_expenses (client catch-up) re-declared off 114: returns the zero-summary {generated:0, reason:''locked''} instead of raising 42501 when the open period is locked. Deferred occurrences are caught up automatically once the payment completes/cancels or the period closes and a new one opens.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 117: settlement close, amount, and confirmation hardening (security audit)
--
-- Three financial-state boundaries are tightened together:
--   1. close_settlement_period now locks the open period row BEFORE fingerprinting
--      and calculating, so an in-flight writer cannot commit a row that is omitted
--      from the archived snapshot.
--   2. requested settlement amounts must match the server's deterministic pairing,
--      not merely remain below total fuel spend.
--   3. paid_pending claims are never promoted to paid by elapsed time alone. Only
--      the recipient can confirm receipt through the normal status RPC.

-- Preserve the battle-tested close implementation and put the serialization
-- boundary in a narrow wrapper. Re-running the migration is safe: the rename only
-- happens once, while CREATE OR REPLACE refreshes the public wrapper.
do $$
begin
  if to_regprocedure('public.close_settlement_period_unlocked(text,uuid,jsonb)') is null then
    if to_regprocedure('public.close_settlement_period(text,uuid,jsonb)') is null then
      raise exception 'close_settlement_period(text, uuid, jsonb) is missing';
    end if;
    execute 'alter function public.close_settlement_period(text, uuid, jsonb) rename to close_settlement_period_unlocked';
  end if;
end
$$;

revoke all on function public.close_settlement_period_unlocked(text, uuid, jsonb) from public;
revoke all on function public.close_settlement_period_unlocked(text, uuid, jsonb) from anon;
revoke all on function public.close_settlement_period_unlocked(text, uuid, jsonb) from authenticated;

create or replace function public.close_settlement_period(
  target_ledger_id text,
  target_period_id uuid,
  period_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  locked_period_id uuid;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;
  if target_period_id is null then
    raise exception 'Missing open settlement period id' using errcode = '22023';
  end if;
  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can close settlement periods' using errcode = '42501';
  end if;

  -- This is deliberately a separate statement before the existing close body.
  -- READ COMMITTED therefore takes a fresh snapshot for every calculation after a
  -- blocked writer commits. Writers already take FOR SHARE on this row; writers
  -- that start later block here until the close commits and then see no open row.
  select sp.id
    into locked_period_id
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    for update of sp;

  if locked_period_id is null then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '22023';
  end if;

  return public.close_settlement_period_unlocked(target_ledger_id, target_period_id, period_snapshot);
end;
$$;

revoke all on function public.close_settlement_period(text, uuid, jsonb) from public;
revoke all on function public.close_settlement_period(text, uuid, jsonb) from anon;
grant execute on function public.close_settlement_period(text, uuid, jsonb) to authenticated;

-- Validate the amount at the table boundary, covering both the SECURITY DEFINER
-- RPC and any direct PostgREST write that RLS permits. The pairing is the same
-- deterministic largest-debtor/largest-creditor algorithm used by the RPC's stale
-- request sweep and by the mobile client.
create or replace function public.enforce_settlement_request_exact_amount()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  computed_settlement jsonb;
  debtor_ids uuid[] := array[]::uuid[];
  debtor_amts numeric[] := array[]::numeric[];
  creditor_ids uuid[] := array[]::uuid[];
  creditor_amts numeric[] := array[]::numeric[];
  di integer := 1;
  ci integer := 1;
  pair_amount numeric;
  expected_pair_amount numeric := null;
  period_is_open boolean;
begin
  if new.status <> 'requested'
     or new.period_id is null
     or new.from_member_id is null
     or new.to_member_id is null then
    return new;
  end if;

  new.currency := upper(coalesce(nullif(btrim(new.currency), ''), 'DKK'));
  if new.currency <> 'DKK' then
    raise exception 'Settlement requests must use DKK' using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' then
    -- A dispute must always be able to reopen a claim. The recipient can issue a
    -- fresh request afterwards if the live balance changed while it was pending,
    -- but the dispute transition itself cannot rewrite the claimed obligation.
    if old.status = 'paid_pending' then
      if new.ledger_id is distinct from old.ledger_id
         or new.period_id is distinct from old.period_id
         or new.from_member_id is distinct from old.from_member_id
         or new.to_member_id is distinct from old.to_member_id
         or new.amount is distinct from old.amount
         or new.currency is distinct from old.currency then
        raise exception 'Disputing a payment claim must preserve its pair, amount, and currency'
          using errcode = '23514';
      end if;
      return new;
    end if;

    -- Reminder bookkeeping updates requested rows without re-requesting them.
    -- Do not turn those background writes into an amount recalculation gate.
    if old.status = 'requested'
       and new.amount is not distinct from old.amount
       and new.from_member_id is not distinct from old.from_member_id
       and new.to_member_id is not distinct from old.to_member_id
       and new.period_id is not distinct from old.period_id
       and new.ledger_id is not distinct from old.ledger_id
       and new.currency is not distinct from old.currency
       and new.requested_at is not distinct from old.requested_at then
      return new;
    end if;
  end if;

  select (sp.status = 'open' and sp.closed_at is null)
    into period_is_open
    from public.settlement_periods sp
    where sp.id = new.period_id
      and sp.ledger_id = new.ledger_id;

  -- Closed-period requests are immutable historical obligations; status-only
  -- transitions continue to use their stored amount.
  if period_is_open is not true then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtext(new.ledger_id || ':settlement:' || new.period_id::text));
  computed_settlement := public.calculate_period_settlement(new.ledger_id, new.period_id);

  select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::uuid[]),
         coalesce(array_agg(round(-((p.value->>'net')::numeric), 2) order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::numeric[])
    into debtor_ids, debtor_amts
    from jsonb_array_elements(computed_settlement->'people') as p(value)
    where (p.value->>'net')::numeric < -0.005;

  select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::uuid[]),
         coalesce(array_agg(round((p.value->>'net')::numeric, 2) order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::numeric[])
    into creditor_ids, creditor_amts
    from jsonb_array_elements(computed_settlement->'people') as p(value)
    where (p.value->>'net')::numeric > 0.005;

  while di <= coalesce(array_length(debtor_ids, 1), 0)
        and ci <= coalesce(array_length(creditor_ids, 1), 0) loop
    pair_amount := round(least(debtor_amts[di], creditor_amts[ci]), 2);
    if debtor_ids[di] = new.from_member_id and creditor_ids[ci] = new.to_member_id then
      expected_pair_amount := pair_amount;
      exit;
    end if;
    debtor_amts[di] := round(debtor_amts[di] - pair_amount, 2);
    creditor_amts[ci] := round(creditor_amts[ci] - pair_amount, 2);
    if debtor_amts[di] <= 0.005 then di := di + 1; end if;
    if creditor_amts[ci] <= 0.005 then ci := ci + 1; end if;
  end loop;

  if expected_pair_amount is null or expected_pair_amount <= 0 then
    raise exception 'This settlement pair is no longer part of the current server calculation. Refresh the app and try again.'
      using errcode = '23514';
  end if;
  if round(coalesce(new.amount, 0), 2) <> expected_pair_amount then
    raise exception 'Settlement request amount does not match the current server calculation. Refresh the app and try again.'
      using errcode = '23514';
  end if;

  new.amount := expected_pair_amount;
  return new;
end;
$$;

revoke all on function public.enforce_settlement_request_exact_amount() from public;
revoke all on function public.enforce_settlement_request_exact_amount() from anon;
revoke all on function public.enforce_settlement_request_exact_amount() from authenticated;

drop trigger if exists enforce_settlement_request_exact_amount_trigger on public.settlement_requests;
create trigger enforce_settlement_request_exact_amount_trigger
before insert or update on public.settlement_requests
for each row execute function public.enforce_settlement_request_exact_amount();

-- Elapsed time is not evidence that money arrived. Keep the old signature as a
-- deployment-compatible no-op while the web scheduler is removed separately.
create or replace function public.claim_due_settlement_confirmations(
  p_max_age_hours integer default 72,
  p_limit integer default 200
)
returns integer
language sql
security definer
set search_path = public
as $$
  select 0::integer
$$;

revoke all on function public.claim_due_settlement_confirmations(integer, integer) from public;
revoke all on function public.claim_due_settlement_confirmations(integer, integer) from anon;
revoke all on function public.claim_due_settlement_confirmations(integer, integer) from authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('117_settlement_integrity_hardening',
        'Settlement integrity hardening (security audit): close_settlement_period now takes an exclusive period-row lock before calculation via a non-bypassable wrapper; requested amounts must equal the server-derived pair amount; elapsed paid_pending claims are no longer auto-confirmed.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 118: confirm-receipt reminders (GV-286) ────────────────────────
-- Nudge the creditor to confirm a paid_pending claim after migration 117 removed
-- the 3-day auto-confirm. Same two-phase claim/confirm + per-lease token discipline
-- as the payment/close reminder engines (migrations 102 + 106).
alter table public.settlement_requests add column if not exists confirm_reminder_claimed_at timestamptz;
alter table public.settlement_requests add column if not exists confirm_reminder_claim_token uuid;
alter table public.settlement_requests add column if not exists last_confirm_reminder_at timestamptz;

create or replace function public.claim_due_confirm_reminders(
  p_limit integer default 200
)
returns table (
  request_id uuid,
  ledger_id text,
  creditor_id uuid,
  creditor_email text,
  debtor_name text,
  amount numeric,
  currency text,
  paid_note text,
  claim_token uuid
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select sr.id
    from public.settlement_requests sr
    join public.ledger_members creditor on creditor.id = sr.to_member_id
    where sr.status = 'paid_pending'
      and sr.paid_claimed_at is not null
      and sr.paid_claimed_at <= now() - interval '24 hours'
      and creditor.is_active = true
      and creditor.email is not null
      and (sr.confirm_reminder_claimed_at is null
           or sr.confirm_reminder_claimed_at <= now() - interval '15 minutes')
      and (sr.last_confirm_reminder_at is null
           or sr.last_confirm_reminder_at <= now() - interval '24 hours')
    order by sr.paid_claimed_at
    limit greatest(coalesce(p_limit, 200), 0)
    for update of sr skip locked
  ),
  claimed as (
    update public.settlement_requests sr
    set confirm_reminder_claimed_at = now(),
        confirm_reminder_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where sr.id = t.id
    returning sr.id as request_id,
              sr.ledger_id as ledger_id,
              sr.from_member_id as debtor_id,
              sr.to_member_id as creditor_id,
              sr.amount as amount,
              sr.currency as currency,
              sr.paid_note as paid_note,
              sr.confirm_reminder_claim_token as claim_token
  )
  select c.request_id,
         c.ledger_id,
         c.creditor_id,
         lower(creditor.email) as creditor_email,
         debtor.name as debtor_name,
         c.amount,
         c.currency,
         c.paid_note,
         c.claim_token
  from claimed c
  left join public.ledger_members creditor on creditor.id = c.creditor_id
  left join public.ledger_members debtor on debtor.id = c.debtor_id;
end;
$$;

revoke all on function public.claim_due_confirm_reminders(integer) from public;
revoke all on function public.claim_due_confirm_reminders(integer) from anon;
revoke all on function public.claim_due_confirm_reminders(integer) from authenticated;
grant execute on function public.claim_due_confirm_reminders(integer) to service_role;

create or replace function public.confirm_confirm_reminders(confirmations jsonb)
returns integer
language sql
security definer
set search_path = public
as $$
  with input as (
    select (elem ->> 'id')::uuid as request_id,
           (elem ->> 'token')::uuid as claim_token,
           (elem ->> 'outcome') as outcome
    from jsonb_array_elements(coalesce(confirmations, '[]'::jsonb)) as elem
    where (elem ->> 'outcome') in ('delivered', 'suppressed_no_device', 'muted')
  ),
  confirmed as (
    update public.settlement_requests sr
    set last_confirm_reminder_at = now(),
        confirm_reminder_claimed_at = null,
        confirm_reminder_claim_token = null,
        updated_at = now()
    from input i
    where sr.id = i.request_id
      and sr.status = 'paid_pending'
      and sr.confirm_reminder_claimed_at is not null
      and sr.confirm_reminder_claim_token = i.claim_token
    returning sr.id as request_id,
              sr.ledger_id as ledger_id,
              sr.from_member_id as debtor_id,
              sr.to_member_id as creditor_id,
              sr.amount as amount,
              i.outcome as outcome
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    )
    select c.ledger_id, 'confirm_reminder_sent', 'Påmindelse om bekræftelse sendt', '',
           null, null,
           jsonb_build_object(
             'settlement_request_id', c.request_id,
             'from_member_id', c.debtor_id,
             'to_member_id', c.creditor_id,
             'amount', c.amount,
             'outcome', c.outcome
           )
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_confirm_reminders(jsonb) from public;
revoke all on function public.confirm_confirm_reminders(jsonb) from anon;
revoke all on function public.confirm_confirm_reminders(jsonb) from authenticated;
grant execute on function public.confirm_confirm_reminders(jsonb) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('118_confirm_receipt_reminders',
        'Confirm-receipt reminders (GV-286): after migration 117 removed the 3-day auto-confirm, a paid_pending claim hangs until the creditor confirms — so nudge the creditor. settlement_requests gains confirm_reminder_claimed_at (lease) + confirm_reminder_claim_token (per-lease token) + last_confirm_reminder_at (cadence). claim_due_confirm_reminders(p_limit) marks due paid_pending requests (paid_claimed_at older than a 24h grace window, not nudged in the last 24h, creditor active + has email) in-flight with a 15-minute lease and a gen_random_uuid() token, returning the creditor push identity + debtor name + amount/currency/paid_note (mirrors claim_due_payment_reminders). confirm_confirm_reminders(confirmations jsonb = [{id,token,outcome}]) advances the cadence only when the lease is live AND the token matches AND the row is still paid_pending, recording the terminal outcome (delivered / suppressed_no_device / muted) in ledger_events metadata; failed sends are never confirmed and retry. No send cap. Both RPCs service_role only.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 119: settlement-rule changes log ledger_events (GV-292)
--
-- update_ledger_settings (newest prior body: migration 107) only patched the
-- ledgers row. A monthly↔running switch, or a repairs-split rule change, therefore
-- left NO ledger_events row — so it was invisible in the activity feed and never
-- pushed to other members' clients (migration 087 lesson: a write RPC that logs no
-- event does not live-sync). This re-declares the function COMPLETELY off the 107
-- body (same signature, same grants/revokes) and, for each settlement rule whose
-- STORED value actually changed, inserts one 'settings_changed' feed event.
--
-- No-op suppression is load-bearing: a non-null param equal to the stored value, or
-- a null param, writes nothing new and must NOT emit an event. We snapshot the old
-- values before the coalesce-patch and compare (is distinct from) against the new
-- ones after, so only a REAL change emits. Only settlement_mode and
-- repairs_split_mode are surfaced; the silent vehicle_info refresh and split
-- defaults stay event-free by design (LedgerContext refreshes vehicle_info on every
-- save and must not spam the feed).

create or replace function public.update_ledger_settings(
  target_ledger_id text,
  settlement_mode_value text default null,
  expense_split_defaults_value jsonb default null,
  vehicle_info_value jsonb default null,
  repairs_split_mode_value text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  old_settlement_mode text;
  old_repairs_split_mode text;
  new_settlement_mode text;
  new_repairs_split_mode text;
  actor_id uuid;
  current_actor_email text;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can update workspace settings' using errcode = '42501';
  end if;

  if settlement_mode_value is not null
     and settlement_mode_value not in ('monthly', 'running') then
    raise exception 'Invalid settlement mode' using errcode = '22023';
  end if;

  if repairs_split_mode_value is not null
     and repairs_split_mode_value not in ('efter_koersel', 'ligeligt', 'deles_ikke') then
    raise exception 'Invalid repairs split mode' using errcode = '22023';
  end if;

  -- Snapshot the settlement rules BEFORE the patch so a real change can be told
  -- apart from a no-op (equal or null param writes nothing new → no event). GV-292.
  select ledgers.settlement_mode, ledgers.repairs_split_mode
    into old_settlement_mode, old_repairs_split_mode
    from public.ledgers
    where ledgers.id = target_ledger_id;

  update public.ledgers set
    settlement_mode        = coalesce(settlement_mode_value, settlement_mode),
    expense_split_defaults = coalesce(expense_split_defaults_value, expense_split_defaults),
    vehicle_info           = coalesce(vehicle_info_value, vehicle_info),
    repairs_split_mode     = coalesce(repairs_split_mode_value, repairs_split_mode),
    updated_at             = now()
  where id = target_ledger_id;

  -- The patch is a coalesce, so the new value is the param when supplied else the
  -- old one — a null or equal param leaves new = old and emits nothing.
  new_settlement_mode := coalesce(settlement_mode_value, old_settlement_mode);
  new_repairs_split_mode := coalesce(repairs_split_mode_value, old_repairs_split_mode);

  actor_id := public.current_ledger_member_id(target_ledger_id);
  current_actor_email := nullif(lower(coalesce(auth.jwt() ->> 'email', '')), '');

  if new_settlement_mode is distinct from old_settlement_mode then
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id,
      'settings_changed',
      'Afregning ændret',
      case new_settlement_mode
        when 'running' then 'Gruppen afregner nu løbende.'
        else 'Gruppen afregner nu månedligt.'
      end,
      actor_id,
      current_actor_email,
      jsonb_build_object(
        'field', 'settlement_mode',
        'old', old_settlement_mode,
        'new', new_settlement_mode
      )
    );
  end if;

  if new_repairs_split_mode is distinct from old_repairs_split_mode then
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id,
      'settings_changed',
      'Reparationsdeling ændret',
      case new_repairs_split_mode
        when 'efter_koersel' then 'Reparationer deles nu efter kørsel.'
        when 'ligeligt' then 'Reparationer deles nu ligeligt.'
        else 'Reparationer deles ikke længere.'
      end,
      actor_id,
      current_actor_email,
      jsonb_build_object(
        'field', 'repairs_split_mode',
        'old', old_repairs_split_mode,
        'new', new_repairs_split_mode
      )
    );
  end if;
end;
$$;

revoke all on function public.update_ledger_settings(text, text, jsonb, jsonb, text) from public;
revoke all on function public.update_ledger_settings(text, text, jsonb, jsonb, text) from anon;
grant execute on function public.update_ledger_settings(text, text, jsonb, jsonb, text) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('119_settings_change_events',
        'Settlement-rule changes log ledger_events (GV-292). update_ledger_settings re-declared off 107 (same 5-arg signature + grants): snapshots settlement_mode + repairs_split_mode before the coalesce-patch and, for each field whose stored value actually changed (is distinct from — a null or equal param is a no-op and emits nothing), inserts one settings_changed feed event. Danish server copy: settlement_mode → "Afregning ændret" / "Gruppen afregner nu løbende." | "Gruppen afregner nu månedligt."; repairs_split_mode → "Reparationsdeling ændret" / "Reparationer deles nu efter kørsel." | "Reparationer deles nu ligeligt." | "Reparationer deles ikke længere." Actor via current_ledger_member_id(), actor_email via auth.jwt(); metadata {field, old, new}. Makes rule switches visible in the feed and live-sync to other members (migration 087 lesson). vehicle_info + split defaults stay event-free by design.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ===========================================================================
-- Migration 120: settlement amount immutability + close-race row locks (GV-293)
-- Appended last so the consolidated schema ends in the same state a fresh
-- replay of every migration produces (last definition wins).
-- ===========================================================================

-- ── FINDING 2: enforce_settlement_entry_lock — closed-period read takes FOR SHARE ──
-- Re-declared off migration 099 (its newest prior body). The ONLY change from 099 is
-- that the closed-period rejection's SELECT now locks the period row FOR SHARE, so a
-- direct trips/fuel/expenses/trip_participants writer synchronizes with the FOR UPDATE
-- that close_settlement_period holds: in-flight writers make the close wait, and writers
-- that begin during the close block until it commits and then see the closed row.
create or replace function public.enforce_settlement_entry_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ledger_id text;
  v_period_id uuid;
  v_trip_deleted_at timestamptz;
  v_guard boolean := false;
  v_check_period_id uuid;
  v_period_closed boolean;
  v_rule_lock boolean;
begin
  if tg_table_name = 'trip_participants' then
    -- Participants have no ledger/period of their own; inherit from the trip.
    -- Changing who shares a trip changes the split, so any insert/update/delete
    -- is guarded unless the parent trip is already a tombstone or is gone.
    if tg_op = 'DELETE' then
      select t.ledger_id, t.period_id, t.deleted_at
        into v_ledger_id, v_period_id, v_trip_deleted_at
        from public.trips t
        where t.id = old.trip_id;
    else
      select t.ledger_id, t.period_id, t.deleted_at
        into v_ledger_id, v_period_id, v_trip_deleted_at
        from public.trips t
        where t.id = new.trip_id;
    end if;

    v_guard := v_ledger_id is not null and v_trip_deleted_at is null;

  elsif tg_op = 'INSERT' then
    v_ledger_id := new.ledger_id;
    v_period_id := new.period_id;
    -- Adding a live entry to a settling period changes the totals.
    v_guard := new.deleted_at is null;

  elsif tg_op = 'DELETE' then
    v_ledger_id := old.ledger_id;
    v_period_id := old.period_id;
    -- Removing a live entry changes the totals; purging a tombstone does not.
    v_guard := old.deleted_at is null;

  else -- UPDATE on trips / fuel_payments / workspace_expenses
    v_ledger_id := coalesce(new.ledger_id, old.ledger_id);
    v_period_id := coalesce(old.period_id, new.period_id);

    if tg_table_name = 'trips' then
      v_guard := (new.start_km is distinct from old.start_km)
              or (new.end_km is distinct from old.end_km)
              or (new.trip_date is distinct from old.trip_date)
              or (new.driver_member_id is distinct from old.driver_member_id)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    elsif tg_table_name = 'fuel_payments' then
      v_guard := (new.amount is distinct from old.amount)
              or (new.liters is distinct from old.liters)
              or (new.payer_member_id is distinct from old.payer_member_id)
              or (new.payment_date is distinct from old.payment_date)
              or (new.full_tank is distinct from old.full_tank)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    elsif tg_table_name = 'workspace_expenses' then
      v_guard := (new.amount_dkk is distinct from old.amount_dkk)
              or (new.paid_by_member_id is distinct from old.paid_by_member_id)
              or (new.split_rule is distinct from old.split_rule)
              or (new.split_config is distinct from old.split_config)
              or (new.period_id is distinct from old.period_id)
              or (new.deleted_at is distinct from old.deleted_at);
    end if;

    -- Editing a row that is a tombstone before and after the change is a no-op
    -- for settlement; leave it alone.
    if old.deleted_at is not null and new.deleted_at is not null then
      v_guard := false;
    end if;
  end if;

  -- Per-workspace override (GV-158, split by GV-243): an operator can disable the
  -- lock-after-payment safety rail for a single workspace via the admin console. The
  -- override is SPLIT across the two protections it used to skip together:
  --   * the requested/paid settlement lock (further below) IS skipped when the flag
  --     is false, so members can freely edit trips/fuel in an OPEN period.
  --   * the closed-period rejection (below) is NOT skipped by this flag — archived
  --     rows in a closed period must always match that period's frozen snapshot_json,
  --     so the closed lock stays enforced regardless of the override.
  -- Only an explicit false relaxes the requested/paid lock; a null (no ledger row
  -- resolved) keeps the always-on behaviour. This lookup no longer returns early.
  if v_ledger_id is not null then
    select l.rule_lock_period_after_payment
      into v_rule_lock
      from public.ledgers l
      where l.id = v_ledger_id;
  end if;

  -- Closed-period rejection (GV-199): no path may add, change, or remove an entry
  -- that belongs to a closed settlement period. Runs before the requested/paid
  -- lock, covers every attached table, and is NOT affected by the override flag
  -- above (GV-243). delete_my_account's GDPR scrubs set the transaction-local
  -- govehlo.pii_scrub GUC to opt out — those touch only non-settlement columns
  -- (e.g. trip note) and must succeed on closed rows.
  if coalesce(current_setting('govehlo.pii_scrub', true), '') <> '1' then
    -- trip_participants has no period_id column, so it must use the parent trip's
    -- period resolved above; only the row-owning tables carry old/new.period_id
    -- (dereferencing it on trip_participants raised 'record has no field period_id'
    -- and broke all trip logging/editing — GV-225).
    if tg_table_name = 'trip_participants' then
      v_check_period_id := v_period_id;
    else
      v_check_period_id := case when tg_op = 'DELETE' then old.period_id else new.period_id end;
    end if;
    if v_check_period_id is not null then
      -- FOR SHARE OF sp (GV-293): synchronize this closed-period read with the FOR
      -- UPDATE close_settlement_period holds on the same row. A direct writer that is
      -- in flight when the close starts holds this share lock, forcing the close to
      -- wait for it; a writer that starts mid-close blocks here on the close's FOR
      -- UPDATE and, once it commits, re-reads the row as closed and is rejected below.
      select (sp.status = 'closed' or sp.closed_at is not null)
        into v_period_closed
        from public.settlement_periods sp
        where sp.id = v_check_period_id
        for share of sp;
      if v_period_closed then
        raise exception
          'This settlement period is closed — entries can no longer be added or changed.'
          using errcode = '22023';
      end if;
    end if;
  end if;

  -- Requested/paid settlement lock — this is the only protection the per-workspace
  -- override relaxes: skipped when the ledger's rule_lock_period_after_payment is
  -- false (GV-243). The closed-period rejection above always runs.
  if v_guard and v_rule_lock is not false
     and public.settlement_entry_is_locked(v_ledger_id, v_period_id) then
    raise exception
      'This settlement period is locked because a payment has been requested or paid. Reopen the payment before changing trips or fuel logs.'
      using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

revoke all on function public.enforce_settlement_entry_lock() from public;
revoke all on function public.enforce_settlement_entry_lock() from anon;
revoke all on function public.enforce_settlement_entry_lock() from authenticated;

-- ── FINDING 1 + 2: enforce_settlement_request_exact_amount ───────────────────────
-- Re-declared off migration 117 (its newest prior body). Two changes:
--   FINDING 1 — the paid_pending-only dispute guard is generalized to a blanket
--     immutability guard: on ANY UPDATE whose result status is not 'requested', the
--     ledger, period, pair, amount, and currency must equal the stored row, closing the
--     requested -> paid_pending / paid_pending -> paid / -> cancelled / -> open direct
--     UPDATE mutation holes. Rows landing in 'requested' still flow into the exact-amount
--     validation below; the reminder-bookkeeping carve-out for requested rows is retained.
--   FINDING 2 — the period-open read locks the period row FOR SHARE so a direct request
--     writer synchronizes with close_settlement_period's FOR UPDATE (see the entry-lock
--     trigger above for the same pattern).
create or replace function public.enforce_settlement_request_exact_amount()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  computed_settlement jsonb;
  debtor_ids uuid[] := array[]::uuid[];
  debtor_amts numeric[] := array[]::numeric[];
  creditor_ids uuid[] := array[]::uuid[];
  creditor_amts numeric[] := array[]::numeric[];
  di integer := 1;
  ci integer := 1;
  pair_amount numeric;
  expected_pair_amount numeric := null;
  period_is_open boolean;
begin
  -- FINDING 1 (GV-293): a settlement request's obligation is immutable across any
  -- status transition that does NOT (re)enter 'requested'. Migration 117 only guarded
  -- the paid_pending -> requested dispute edge and early-returned for everything else,
  -- so a settlement party could rewrite the ledger, period, pair, amount, or currency
  -- through a direct RLS UPDATE while claiming/confirming/cancelling a payment. Any
  -- UPDATE whose result is not 'requested' must therefore preserve all six fields.
  -- Transitions INTO 'requested' (fresh request, re-request, dispute) fall through to
  -- the exact-amount validation below, which pins the amount to the server pairing.
  -- Reminder bookkeeping (claim tokens / timestamps) never changes these six fields,
  -- so it is unaffected.
  if tg_op = 'UPDATE' and new.status <> 'requested' then
    if new.ledger_id is distinct from old.ledger_id
       or new.period_id is distinct from old.period_id
       or new.from_member_id is distinct from old.from_member_id
       or new.to_member_id is distinct from old.to_member_id
       or new.amount is distinct from old.amount
       or new.currency is distinct from old.currency then
      raise exception 'A settlement request''s ledger, period, pair, amount, and currency are immutable once requested; only its status may change'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if new.status <> 'requested'
     or new.period_id is null
     or new.from_member_id is null
     or new.to_member_id is null then
    return new;
  end if;

  new.currency := upper(coalesce(nullif(btrim(new.currency), ''), 'DKK'));
  if new.currency <> 'DKK' then
    raise exception 'Settlement requests must use DKK' using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' then
    -- A dispute must always be able to reopen a claim. The recipient can issue a
    -- fresh request afterwards if the live balance changed while it was pending,
    -- but the dispute transition itself cannot rewrite the claimed obligation.
    if old.status = 'paid_pending' then
      if new.ledger_id is distinct from old.ledger_id
         or new.period_id is distinct from old.period_id
         or new.from_member_id is distinct from old.from_member_id
         or new.to_member_id is distinct from old.to_member_id
         or new.amount is distinct from old.amount
         or new.currency is distinct from old.currency then
        raise exception 'Disputing a payment claim must preserve its pair, amount, and currency'
          using errcode = '23514';
      end if;
      return new;
    end if;

    -- Reminder bookkeeping updates requested rows without re-requesting them.
    -- Do not turn those background writes into an amount recalculation gate.
    if old.status = 'requested'
       and new.amount is not distinct from old.amount
       and new.from_member_id is not distinct from old.from_member_id
       and new.to_member_id is not distinct from old.to_member_id
       and new.period_id is not distinct from old.period_id
       and new.ledger_id is not distinct from old.ledger_id
       and new.currency is not distinct from old.currency
       and new.requested_at is not distinct from old.requested_at then
      return new;
    end if;
  end if;

  -- FOR SHARE OF sp (GV-293): synchronize this period-open read with the FOR UPDATE
  -- close_settlement_period holds on the same row, so an in-flight requested-status
  -- writer blocks the close and a writer that starts mid-close waits for the commit
  -- and then sees the period as closed (falling through to the stored-amount path).
  select (sp.status = 'open' and sp.closed_at is null)
    into period_is_open
    from public.settlement_periods sp
    where sp.id = new.period_id
      and sp.ledger_id = new.ledger_id
    for share of sp;

  -- Closed-period requests are immutable historical obligations; status-only
  -- transitions continue to use their stored amount.
  if period_is_open is not true then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtext(new.ledger_id || ':settlement:' || new.period_id::text));
  computed_settlement := public.calculate_period_settlement(new.ledger_id, new.period_id);

  select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::uuid[]),
         coalesce(array_agg(round(-((p.value->>'net')::numeric), 2) order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::numeric[])
    into debtor_ids, debtor_amts
    from jsonb_array_elements(computed_settlement->'people') as p(value)
    where (p.value->>'net')::numeric < -0.005;

  select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::uuid[]),
         coalesce(array_agg(round((p.value->>'net')::numeric, 2) order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::numeric[])
    into creditor_ids, creditor_amts
    from jsonb_array_elements(computed_settlement->'people') as p(value)
    where (p.value->>'net')::numeric > 0.005;

  while di <= coalesce(array_length(debtor_ids, 1), 0)
        and ci <= coalesce(array_length(creditor_ids, 1), 0) loop
    pair_amount := round(least(debtor_amts[di], creditor_amts[ci]), 2);
    if debtor_ids[di] = new.from_member_id and creditor_ids[ci] = new.to_member_id then
      expected_pair_amount := pair_amount;
      exit;
    end if;
    debtor_amts[di] := round(debtor_amts[di] - pair_amount, 2);
    creditor_amts[ci] := round(creditor_amts[ci] - pair_amount, 2);
    if debtor_amts[di] <= 0.005 then di := di + 1; end if;
    if creditor_amts[ci] <= 0.005 then ci := ci + 1; end if;
  end loop;

  if expected_pair_amount is null or expected_pair_amount <= 0 then
    raise exception 'This settlement pair is no longer part of the current server calculation. Refresh the app and try again.'
      using errcode = '23514';
  end if;
  if round(coalesce(new.amount, 0), 2) <> expected_pair_amount then
    raise exception 'Settlement request amount does not match the current server calculation. Refresh the app and try again.'
      using errcode = '23514';
  end if;

  new.amount := expected_pair_amount;
  return new;
end;
$$;

revoke all on function public.enforce_settlement_request_exact_amount() from public;
revoke all on function public.enforce_settlement_request_exact_amount() from anon;
revoke all on function public.enforce_settlement_request_exact_amount() from authenticated;

drop trigger if exists enforce_settlement_request_exact_amount_trigger on public.settlement_requests;
create trigger enforce_settlement_request_exact_amount_trigger
before insert or update on public.settlement_requests
for each row execute function public.enforce_settlement_request_exact_amount();

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('120_settlement_immutability_and_close_lock',
        'Settlement immutability + close-race row locks (GV-293). FINDING 1: enforce_settlement_request_exact_amount (re-declared off 117) generalizes the paid_pending dispute guard — ANY UPDATE whose result status is not ''requested'' must preserve ledger_id, period_id, from_member_id, to_member_id, amount, and currency (errcode 23514), closing the requested->paid_pending / paid_pending->paid / ->cancelled / ->open direct-UPDATE mutation holes; transitions INTO ''requested'' still validate against the server pairing and the requested-row reminder carve-out is retained. FINDING 2: the period-status reads in enforce_settlement_entry_lock (re-declared off 099; covers trips/fuel_payments/workspace_expenses/trip_participants) and enforce_settlement_request_exact_amount now take FOR SHARE OF the settlement_periods row, so a direct PostgREST writer synchronizes with close_settlement_period''s FOR UPDATE: an in-flight writer blocks the close and a writer starting mid-close waits for the commit and then sees the period closed.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 121: complete the settlement period boundary for direct writes.
--
-- Migration 120 correctly made request amounts immutable on paid-ish transitions
-- and made the existing entry trigger take a FOR SHARE lock. This follow-up covers
-- three adjacent direct-PostgREST paths that the single-current-period check does
-- not cover:
--
--   * a request/entry could combine a ledger_id with a period_id owned by another
--     ledger; for a requested payment that made the exact-amount lookup return no
--     row and fall through as though the period were historical;
--   * an UPDATE moving an entry checked/locked NEW.period_id only, so it could move
--     a row out of an OLD closed period;
--   * vehicle_repairs participates in settlement calculations but uses a separate
--     update/delete guard and had no direct-insert period-row serialization.
--
-- The guards below are deliberately table-boundary protections. RPC callers keep
-- their existing behavior; direct inserts with no period are bound to the ledger's
-- open period, and all affected old/new periods are locked in UUID order.

create or replace function public.enforce_settlement_request_period_identity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.period_id is null then
    raise exception 'Settlement requests must belong to a settlement period'
      using errcode = '23514';
  end if;

  if tg_op = 'UPDATE'
     and (new.ledger_id is distinct from old.ledger_id
          or new.period_id is distinct from old.period_id
          or new.from_member_id is distinct from old.from_member_id
          or new.to_member_id is distinct from old.to_member_id) then
    raise exception 'Settlement request ledger, period, and parties are immutable'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.settlement_periods sp
    where sp.id = new.period_id
      and sp.ledger_id = new.ledger_id
  ) then
    raise exception 'Settlement request period must belong to the same ledger as the request'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

revoke all on function public.enforce_settlement_request_period_identity() from public;
revoke all on function public.enforce_settlement_request_period_identity() from anon;
revoke all on function public.enforce_settlement_request_period_identity() from authenticated;

drop trigger if exists assert_settlement_request_period_identity on public.settlement_requests;
create trigger assert_settlement_request_period_identity
before insert or update of ledger_id, period_id, from_member_id, to_member_id
on public.settlement_requests
for each row execute function public.enforce_settlement_request_period_identity();

create or replace function public.enforce_settlement_entry_period_boundary()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_period_id uuid;
  new_period_id uuid;
  old_ledger_id text;
  new_ledger_id text;
  period_row record;
begin
  -- Account deletion scrubs only PII fields on historical rows. Preserve the
  -- transaction-local bypass used by the existing closed-period guards.
  if coalesce(current_setting('govehlo.pii_scrub', true), '') = '1' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_table_name = 'trip_participants' then
    if tg_op in ('UPDATE', 'DELETE') then
      select t.period_id, t.ledger_id into old_period_id, old_ledger_id
      from public.trips t
      where t.id = old.trip_id;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      select t.period_id, t.ledger_id into new_period_id, new_ledger_id
      from public.trips t
      where t.id = new.trip_id;
    end if;
  elsif tg_table_name = 'vehicle_repairs' then
    if tg_op in ('UPDATE', 'DELETE') then
      old_period_id := old.period_id;
      old_ledger_id := old.ledger_id;
      if old_period_id is null then
        select sp.id into old_period_id
        from public.settlement_periods sp
        where sp.ledger_id = old.ledger_id
          and old.created_at >= sp.opened_at
          and (sp.closed_at is null or old.created_at < sp.closed_at)
        order by sp.opened_at desc
        limit 1;
      end if;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      new_period_id := new.period_id;
      new_ledger_id := new.ledger_id;
    end if;
  else
    if tg_op in ('UPDATE', 'DELETE') then
      old_period_id := old.period_id;
      old_ledger_id := old.ledger_id;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      new_period_id := new.period_id;
      new_ledger_id := new.ledger_id;
    end if;
  end if;

  -- Legitimate RPCs already supply a period. Bind a direct row insert to the
  -- ledger's current open period so null cannot evade close serialization.
  if tg_table_name <> 'trip_participants'
     and tg_op = 'INSERT'
     and new_period_id is null then
    select sp.id into new_period_id
    from public.settlement_periods sp
    where sp.ledger_id = new_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    order by sp.opened_at desc
    limit 1;

    if new_period_id is null then
      raise exception 'No open settlement period exists for this ledger'
        using errcode = '22023';
    end if;
    new.period_id := new_period_id;
  end if;

  for period_row in
    select sp.id, sp.ledger_id, sp.status, sp.closed_at
    from public.settlement_periods sp
    where sp.id in (old_period_id, new_period_id)
    order by sp.id
    for share of sp
  loop
    if (period_row.id = old_period_id and period_row.ledger_id is distinct from old_ledger_id)
       or (period_row.id = new_period_id and period_row.ledger_id is distinct from new_ledger_id) then
      raise exception 'Settlement entry period must belong to the same ledger as the entry'
        using errcode = '23514';
    end if;

    if period_row.status = 'closed' or period_row.closed_at is not null then
      raise exception
        'This settlement period is closed -- entries can no longer be added or changed.'
        using errcode = '22023';
    end if;
  end loop;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

revoke all on function public.enforce_settlement_entry_period_boundary() from public;
revoke all on function public.enforce_settlement_entry_period_boundary() from anon;
revoke all on function public.enforce_settlement_entry_period_boundary() from authenticated;

